void main() {
  int fibonacci(int n, Map<int, int> memo) {
    if (n <= 1) return n;
    if (memo.containsKey(n)) return memo[n]!;
    memo[n] = fibonacci(n - 1, memo) + fibonacci(n - 2, memo);
    return memo[n]!;
  }

  final memo = <int, int>{};
