  List<String> X = s1.split('');
  List<String> Y = s2.split('');
  int m = X.length;
  int n = Y.length;

  // Create a 2D list to store lengths of LCS
  List<List<int>> lcs = List.generate(m + 1, (_) => List.filled(n + 1, 0));

  // Build the lcs table in bottom-up fashion
  for (int i = 0; i <= m; i++) {
    for (int j = 0; j <= n; j++) {
      if (i == 0 || j == 0) {
        lcs[i][j] = 0;
      } else if (X[i - 1] == Y[j - 1]) {
        lcs[i][j] = lcs[i - 1][j - 1] + 1;
      } else {
        lcs[i][j] = lcs[i - 1][j] > lcs[i][j - 1] ? lcs[i - 1][j] : lcs[i][j - 1];
      }
    }
  }

  // Recover the LCS string from the table
  int index = lcs[m][n];
  List<String> lcsStr = List.filled(index, '');
  int i = m, j = n;
  while (i > 0 && j > 0) {
    if (X[i - 1] == Y[j - 1]) {
      lcsStr[index - 1] = X[i - 1];
      i--;
      j--;
      index--;
    } else if (lcs[i - 1][j] > lcs[i][j - 1]) {
      i--;
    } else {
      j--;
    }
  }

  print('String 1: $s1');
  print('String 2: $s2');
  print('Longest Common Subsequence: ${lcsStr.join()}');
  print('Length: ${lcs[m][n]}');
}

