import 'dart:math';

enum Color { red, black }

class RBNode<T extends Comparable> {
  T key;
  Color color;
  RBNode<T>? left;
  RBNode<T>? right;
  RBNode<T>? parent;

  RBNode(this.key, {this.color = Color.red, this.left, this.right, this.parent});
}

class RedBlackTree<T extends Comparable> {
  RBNode<T>? root;

  void insert(T key) {
    RBNode<T> node = RBNode<T>(key);
    RBNode<T>? y;
    RBNode<T>? x = root;

    while (x != null) {
      y = x;
      if (node.key.compareTo(x.key) < 0) {
        x = x.left;
      } else {
        x = x.right;
      }
    }
    node.parent = y;
    if (y == null) {
      root = node;
    } else if (node.key.compareTo(y.key) < 0) {
      y.left = node;
    } else {
      y.right = node;
    }
    node.color = Color.red;
    _insertFixup(node);
  }

  void _insertFixup(RBNode<T> z) {
    while (z.parent != null && z.parent!.color == Color.red) {
      if (z.parent == z.parent!.parent?.left) {
        RBNode<T>? y = z.parent!.parent?.right;
        if (y != null && y.color == Color.red) {
          z.parent!.color = Color.black;
          y.color = Color.black;
          z.parent!.parent!.color = Color.red;
          z = z.parent!.parent!;
        } else {
          if (z == z.parent!.right) {
            z = z.parent!;
            _leftRotate(z);
          }
          z.parent!.color = Color.black;
          z.parent!.parent!.color = Color.red;
          if (z.parent!.parent != null) {
            _rightRotate(z.parent!.parent!);
          }
        }
      } else {
        RBNode<T>? y = z.parent!.parent?.left;
        if (y != null && y.color == Color.red) {
          z.parent!.color = Color.black;
          y.color = Color.black;
          z.parent!.parent!.color = Color.red;
          z = z.parent!.parent!;
        } else {
          if (z == z.parent!.left) {
            z = z.parent!;
            _rightRotate(z);
          }
          z.parent!.color = Color.black;
          z.parent!.parent!.color = Color.red;
          if (z.parent!.parent != null) {
            _leftRotate(z.parent!.parent!);
          }
        }
      }
    }
    root?.color = Color.black;
  }

  void _leftRotate(RBNode<T> x) {
    RBNode<T>? y = x.right;
    if (y == null) return;
    x.right = y.left;
    if (y.left != null) {
      y.left!.parent = x;
    }
    y.parent = x.parent;
    if (x.parent == null) {
      root = y;
    } else if (x == x.parent!.left) {
      x.parent!.left = y;
    } else {
      x.parent!.right = y;
    }
    y.left = x;
    x.parent = y;
  }

  void _rightRotate(RBNode<T> y) {
    RBNode<T>? x = y.left;
    if (x == null) return;
    y.left = x.right;
    if (x.right != null) {
      x.right!.parent = y;
    }
    x.parent = y.parent;
    if (y.parent == null) {
      root = x;
    } else if (y == y.parent!.right) {
      y.parent!.right = x;
    } else {
      y.parent!.left = x;
    }
    x.right = y;
    y.parent = x;
  }

  void inorder(void Function(T key, Color color) visit) {
    void _inorder(RBNode<T>? node) {
      if (node == null) return;
      _inorder(node.left);
      visit(node.key, node.color);
      _inorder(node.right);
    }
    _inorder(root);
  }

  bool contains(T key) {
    RBNode<T>? x = root;
    while (x != null) {
      int cmp = key.compareTo(x.key);
      if (cmp == 0) return true;
      x = cmp < 0 ? x.left : x.right;
    }
    return false;
  }
}

