  // Function to build the longest prefix suffix (LPS) array
  List<int> computeLPSArray(String pattern) {
    int m = pattern.length;
    List<int> lps = List.filled(m, 0);
    int len = 0; // length of the previous longest prefix suffix
    int i = 1;

    while (i < m) {
      if (pattern[i] == pattern[len]) {
        len++;
        lps[i] = len;
        i++;
      } else {
        if (len != 0) {
          len = lps[len - 1];
        } else {
          lps[i] = 0;
          i++;
        }
      }
    }
    return lps;
  }

  // KMP search function
  List<int> kmpSearch(String text, String pattern) {
    int n = text.length;
    int m = pattern.length;
    List<int> result = [];

    if (m == 0 || n == 0 || m > n) {
      return result;
    }

    List<int> lps = computeLPSArray(pattern);

    int i = 0; // index for text
    int j = 0; // index for pattern

    while (i < n) {
      if (pattern[j] == text[i]) {
        i++;
        j++;
      }
      if (j == m) {
        result.add(i - j); // Match found at index (i - j)
        j = lps[j - 1];
      } else if (i < n && pattern[j] != text[i]) {
        if (j != 0) {
          j = lps[j - 1];
        } else {
          i++;
        }
      }
    }

    return result;
  }

  // Example usage
  String text = "ababcabcabababd";
  String pattern = "ababd";

