// Miller-Rabin primality test for n with k rounds
bool millerRabinPrimality(BigInt n, int k) {
  if (n == BigInt.two || n == BigInt.from(3)) return true;
  if (n < BigInt.two || n.isEven) return false;

  // Write n-1 as 2^r * d
  BigInt d = n - BigInt.one;
  int r = 0;
  while (d.isEven) {
    d ~/= BigInt.two;
    r += 1;
  }

  var rand = Random.secure();

  for (int i = 0; i < k; i++) {
    // Pick a random integer a in [2, n-2]
    BigInt a = _randomBigIntInRange(BigInt.two, n - BigInt.two, rand);
    BigInt x = a.modPow(d, n);

    if (x == BigInt.one || x == n - BigInt.one) continue;

    bool continueWitnessLoop = false;
    for (int j = 0; j < r - 1; j++) {
      x = x.modPow(BigInt.two, n);
      if (x == n - BigInt.one) {
        continueWitnessLoop = true;
        break;
      }
    }
    if (continueWitnessLoop) continue;

    // Composite
    return false;
  }
  // Probably prime
  return true;
}

// Generate a random BigInt in [min, max] inclusive
BigInt _randomBigIntInRange(BigInt min, BigInt max, Random rand) {
  BigInt range = max - min + BigInt.one;
  int bitLength = range.bitLength;
  BigInt result;
  do {
    result = _randomBigInt(bitLength, rand);
  } while (result > range);
  return result + min;
}

// Generate a random BigInt of given bit length
BigInt _randomBigInt(int bitLength, Random rand) {
  int bytes = (bitLength + 7) >> 3;
  var b = List<int>.generate(bytes, (_) => rand.nextInt(256));
  BigInt result = BigInt.zero;
  for (int i = 0; i < b.length; i++) {
    result = (result << 8) | BigInt.from(b[i]);
  }
  return result;
}

