void main() {
  // Extended Euclidean Algorithm to find modular inverse of a mod m
  int modInverse(int a, int m) {
    int m0 = m;
    int y = 0, x = 1;

    if (m == 1) return 0;

    while (a > 1) {
      // q is quotient
      int q = a ~/ m;
      int t = m;

      // m is remainder now, process same as Euclid's algo
      m = a % m;
      a = t;
      t = y;

      // Update y and x
      y = x - q * y;
      x = t;
    }

    // Make x positive
    if (x < 0) x += m0;

    return x;
  }

  // Example usage:
  int a = 3;
  int m = 11;
  int inv = modInverse(a, m);
  if ((a * inv) % m == 1) {
    print('Modular inverse of $a mod $m is $inv');
  } else {
    print('Modular inverse does not exist');
  }
}

