  // Example usage: Build HLD from a tree and answer path queries.
  // Tree:
  // 1
  // ├─ 2
  // │  ├─ 4
  // │  └─ 5
  // └─ 3
  //     ├─ 6
  //     └─ 7

  int n = 7;
  List<List<int>> tree = List.generate(n + 1, (_) => []);
  void addEdge(int u, int v) {
    tree[u].add(v);
    tree[v].add(u);
  }

  addEdge(1, 2);
  addEdge(1, 3);
  addEdge(2, 4);
  addEdge(2, 5);
  addEdge(3, 6);
  addEdge(3, 7);

  // HLD structures
  List<int> parent = List.filled(n + 1, 0);
  List<int> depth = List.filled(n + 1, 0);
  List<int> heavy = List.filled(n + 1, -1);
  List<int> size = List.filled(n + 1, 0);
  List<int> head = List.filled(n + 1, 0);
  List<int> pos = List.filled(n + 1, 0);

  int curPos = 1;

  // 1. DFS to compute sizes and heavy child
  void dfs(int v, int p) {
    size[v] = 1;
    int maxSubtree = 0;
    for (int u in tree[v]) {
      if (u == p) continue;
      parent[u] = v;
      depth[u] = depth[v] + 1;
      dfs(u, v);
      size[v] += size[u];
      if (size[u] > maxSubtree) {
        maxSubtree = size[u];
        heavy[v] = u;
      }
    }
  }

  // 2. Decompose the tree
  void decompose(int v, int h) {
    head[v] = h;
    pos[v] = curPos++;
    if (heavy[v] != -1) {
      decompose(heavy[v], h);
    }
    for (int u in tree[v]) {
      if (u != parent[v] && u != heavy[v]) {
        decompose(u, u);
      }
    }
  }

  dfs(1, 0);
  decompose(1, 1);

  // Print decomposition info
  print('Node | Parent | Depth | Heavy | Head | Pos');
  for (int v = 1; v <= n; ++v) {
    print(
        '$v\t| ${parent[v]}\t| ${depth[v]}\t| ${heavy[v] == -1 ? "-" : heavy[v]}\t| ${head[v]}\t| ${pos[v]}');
  }

  // Example: Query path from u to v (returns list of (head, l, r) segments)
  List<List<int>> getPathSegments(int u, int v) {
    List<List<int>> res = [];
    while (head[u] != head[v]) {
      if (depth[head[u]] < depth[head[v]]) {
        int tmp = u;
        u = v;
        v = tmp;
      }
      res.add([head[u], pos[head[u]], pos[u]]);
      u = parent[head[u]];
    }
    if (depth[u] > depth[v]) {
      int tmp = u;
      u = v;
      v = tmp;
    }
    res.add([head[u], pos[u], pos[v]]);
    return res;
  }

  // Example query: path from 4 to 7
  int u = 4, v = 7;
  print('\nPath segments from $u to $v:');
  var segments = getPathSegments(u, v);
  for (var seg in segments) {
    print('Chain head: ${seg[0]}, pos: ${seg[1]} to ${seg[2]}');
  }
}

