  // 2---3
  // |
  // 4
  Map<int, List<int>> graph = {
    0: [1, 2],
    1: [0, 2, 3],
    2: [0, 1, 3, 4],
    3: [1, 2],
    4: [2],
  };

  int n = graph.length;
  List<bool> visited = List.filled(n, false);
  List<int> disc = List.filled(n, -1); // Discovery times of visited vertices
  List<int> low = List.filled(n, -1);  // Earliest visited vertex (the minimum discovery time) that can be reached
  List<int> parent = List.filled(n, -1);
  Set<int> articulationPoints = {};

  int time = 0;

  void dfs(int u) {
    visited[u] = true;
    disc[u] = low[u] = time++;
    int children = 0;

    for (int v in graph[u]!) {
      if (!visited[v]) {
        parent[v] = u;
        children++;
        dfs(v);

        low[u] = low[u] < low[v] ? low[u] : low[v];

        // (1) u is root of DFS tree and has two or more children.
        if (parent[u] == -1 && children > 1) {
          articulationPoints.add(u);
        }
        // (2) If u is not root and low value of one of its child is more than discovery value of u.
        if (parent[u] != -1 && low[v] >= disc[u]) {
          articulationPoints.add(u);
        }
