  // Example graph as adjacency list
  // 0---1---2
  // |   |
  // 3---4
  //
  // Bridges: (1,2)
  final n = 5; // Number of vertices
  final adj = [
    [1, 3],      // 0
    [0, 2, 4],   // 1
    [1],         // 2
    [0, 4],      // 3
    [1, 3],      // 4
  ];

  List<List<int>> findBridges(int n, List<List<int>> adj) {
    final visited = List<bool>.filled(n, false);
    final tin = List<int>.filled(n, -1);
    final low = List<int>.filled(n, -1);
    int timer = 0;
    final bridges = <List<int>>[];

    void dfs(int v, int p) {
      visited[v] = true;
      tin[v] = low[v] = timer++;
      for (final to in adj[v]) {
        if (to == p) continue;
        if (visited[to]) {
          low[v] = low[v] < tin[to] ? low[v] : tin[to];
        } else {
          dfs(to, v);
          low[v] = low[v] < low[to] ? low[v] : low[to];
          if (low[to] > tin[v]) {
            bridges.add([v, to]);
          }
        }
      }
    }

    for (int i = 0; i < n; i++) {
      if (!visited[i]) dfs(i, -1);
    }
    return bridges;
  }

