import 'dart:collection';
import 'dart:io';

@pragma('vm:entry-point')
void main() {
  // Example graph as adjacency matrix
  // 0: source, 5: sink
  List<List<int>> capacity = [
    //0  1  2  3  4  5
    [ 0,16,13, 0, 0, 0], // 0
    [ 0, 0,10,12, 0, 0], // 1
    [ 0, 4, 0, 0,14, 0], // 2
    [ 0, 0, 9, 0, 0,20], // 3
    [ 0, 0, 0, 7, 0, 4], // 4
    [ 0, 0, 0, 0, 0, 0], // 5
  ];

  int n = capacity.length;
  int source = 0;
  int sink = n - 1;

  // Edmonds-Karp algorithm
  int edmondsKarp(List<List<int>> cap, int s, int t) {
    List<List<int>> flow = List.generate(n, (_) => List.filled(n, 0));
    int maxFlow = 0;

    while (true) {
      // BFS to find shortest augmenting path
      List<int?> parent = List.filled(n, null);
      Queue<int> queue = Queue<int>();
      queue.add(s);
      parent[s] = -1;

      while (queue.isNotEmpty) {
        int u = queue.removeFirst();
        for (int v = 0; v < n; v++) {
          if (parent[v] == null && cap[u][v] - flow[u][v] > 0) {
            parent[v] = u;
            if (v == t) break;
            queue.add(v);
          }
        }
      }

      // No more augmenting paths
      if (parent[t] == null) break;

      // Find minimum residual capacity along the path
      int pathFlow = 1 << 30;
      int v = t;
      while (v != s) {
        int u = parent[v]!;
        pathFlow = pathFlow < (cap[u][v] - flow[u][v])
            ? pathFlow
            : (cap[u][v] - flow[u][v]);
        v = u;
      }

      // Update flow along the path
      v = t;
      while (v != s) {
        int u = parent[v]!;
        flow[u][v] += pathFlow;
        flow[v][u] -= pathFlow;
        v = u;
      }

      maxFlow += pathFlow;
    }

    return maxFlow;
  }

  int result = edmondsKarp(capacity, source, sink);
  print('Maximum flow: $result');
}

