import 'dart:collection';
import 'dart:math';

class Edge {
  int to, rev, cap, cost, flow;
  Edge(this.to, this.rev, this.cap, this.cost, this.flow);
}

class MinCostFlow {
  final int n;
  late List<List<Edge>> graph;

  MinCostFlow(this.n) {
    graph = List.generate(n, (_) => []);
  }

  void addEdge(int from, int to, int cap, int cost) {
    graph[from].add(Edge(to, graph[to].length, cap, cost, 0));
    graph[to].add(Edge(from, graph[from].length - 1, 0, -cost, 0));
  }

  /// Returns (flow, cost)
  /// Finds min-cost flow of up to [maxFlow] units from [s] to [t].
  /// If you want the flow to be exactly [maxFlow], check if flow == maxFlow.
  Tuple2<int, int> minCostFlow(int s, int t, int maxFlow) {
    int flow = 0, cost = 0;
    List<int> h = List.filled(n, 0); // Potential
    List<int> prevv = List.filled(n, 0);
    List<int> preve = List.filled(n, 0);

    const int INF = 1 << 30;

    while (flow < maxFlow) {
      List<int> dist = List.filled(n, INF);
      dist[s] = 0;
      PriorityQueue<Tuple2<int, int>> pq = PriorityQueue((a, b) => a.item1 - b.item1);
      pq.add(Tuple2(0, s));
      while (pq.isNotEmpty) {
        var p = pq.removeFirst();
        int d = p.item1, v = p.item2;
        if (dist[v] < d) continue;
        for (int i = 0; i < graph[v].length; i++) {
          Edge e = graph[v][i];
          if (e.cap > e.flow) {
            int to = e.to;
            int costWithPotential = e.cost + h[v] - h[to];
            if (dist[to] > dist[v] + costWithPotential) {
              dist[to] = dist[v] + costWithPotential;
              prevv[to] = v;
              preve[to] = i;
              pq.add(Tuple2(dist[to], to));
            }
          }
        }
      }
      if (dist[t] == INF) {
        break;
      }
      for (int v = 0; v < n; v++) {
        h[v] += dist[v] < INF ? dist[v] : 0;
      }

      // Add as much as possible
      int d = maxFlow - flow;
      for (int v = t; v != s; v = prevv[v]) {
        d = min(d, graph[prevv[v]][preve[v]].cap - graph[prevv[v]][preve[v]].flow);
      }
      flow += d;
      cost += d * h[t];
      for (int v = t; v != s; v = prevv[v]) {
        Edge e = graph[prevv[v]][preve[v]];
        e.flow += d;
        graph[v][e.rev].flow -= d;
      }
    }
    return Tuple2(flow, cost);
  }
}

class Tuple2<T1, T2> {
  final T1 item1;
  final T2 item2;
  Tuple2(this.item1, this.item2);
}

class PriorityQueue<T> {
  final List<T> _heap = [];
  final int Function(T, T) _compare;
  PriorityQueue(this._compare);

  void add(T value) {
    _heap.add(value);
    _siftUp(_heap.length - 1);
  }

  T removeFirst() {
    if (_heap.isEmpty) throw StateError('No element');
    T first = _heap.first;
    T last = _heap.removeLast();
    if (_heap.isNotEmpty) {
      _heap[0] = last;
      _siftDown(0);
    }
    return first;
  }

  bool get isNotEmpty => _heap.isNotEmpty;

  void _siftUp(int i) {
    while (i > 0) {
      int p = (i - 1) >> 1;
      if (_compare(_heap[i], _heap[p]) >= 0) break;
      var tmp = _heap[i];
      _heap[i] = _heap[p];
      _heap[p] = tmp;
      i = p;
    }
  }

  void _siftDown(int i) {
    int n = _heap.length;
    while (true) {
      int l = (i << 1) + 1, r = (i << 1) + 2, smallest = i;
      if (l < n && _compare(_heap[l], _heap[smallest]) < 0) smallest = l;
      if (r < n && _compare(_heap[r], _heap[smallest]) < 0) smallest = r;
      if (smallest == i) break;
      var tmp = _heap[i];
      _heap[i] = _heap[smallest];
      _heap[smallest] = tmp;
      i = smallest;
    }
  }
}

