import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Example cost matrix (you can change this)
  List<List<int>> cost = [
    [9, 11, 14, 11, 7],
    [6, 15, 13, 13, 10],
    [12, 13, 6, 8, 8],
    [11, 9, 10, 12, 9],
    [7, 12, 14, 10, 14]
  ];

  int n = cost.length;
  List<List<int>> matrix = List.generate(
      n, (i) => List<int>.from(cost[i])); // Copy of cost matrix

  // Step 1: Subtract row minima
  for (int i = 0; i < n; i++) {
    int rowMin = matrix[i].reduce(min);
    for (int j = 0; j < n; j++) {
      matrix[i][j] -= rowMin;
    }
  }

  // Step 2: Subtract column minima
  for (int j = 0; j < n; j++) {
    int colMin = matrix[0][j];
    for (int i = 1; i < n; i++) {
      if (matrix[i][j] < colMin) colMin = matrix[i][j];
    }
    for (int i = 0; i < n; i++) {
      matrix[i][j] -= colMin;
    }
  }

  // Helper functions for covering zeros, marking, etc.
  List<List<int>> mask = List.generate(n, (_) => List.filled(n, 0));
  List<bool> rowCover = List.filled(n, false);
  List<bool> colCover = List.filled(n, false);

  // 0: nothing, 1: starred zero, 2: primed zero

  // Step 3: Star zeros
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (matrix[i][j] == 0 && !rowCover[i] && !colCover[j]) {
        mask[i][j] = 1;
        rowCover[i] = true;
        colCover[j] = true;
      }
    }
  }
  // Reset covers
  for (int i = 0; i < n; i++) rowCover[i] = false;
  for (int i = 0; i < n; i++) colCover[i] = false;

  // Step 4: Cover columns with starred zeros
  void coverColumnsWithStarredZero() {
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        if (mask[i][j] == 1) {
          colCover[j] = true;
        }
      }
    }
  }

  coverColumnsWithStarredZero();

  bool allColumnsCovered() {
    int count = 0;
    for (int j = 0; j < n; j++) if (colCover[j]) count++;
    return count >= n;
  }

  // Main loop
  while (!allColumnsCovered()) {
    // Step 5: Find a noncovered zero and prime it
    bool done = false;
    int zeroRow = -1, zeroCol = -1;
    while (!done) {
      bool found = false;
      for (int i = 0; i < n && !found; i++) {
        if (!rowCover[i]) {
          for (int j = 0; j < n && !found; j++) {
            if (!colCover[j] && matrix[i][j] == 0) {
              mask[i][j] = 2; // Prime
              // Check if there is a starred zero in this row
              int starCol = mask[i].indexOf(1);
              if (starCol == -1) {
                // Step 6: augmenting path
                zeroRow = i;
                zeroCol = j;
                done = true;
              } else {
                rowCover[i] = true;
                colCover[starCol] = false;
              }
              found = true;
            }
          }
        }
      }
      if (!found) {
        // Step 7: Adjust the matrix
        int minUncovered = 1 << 30;
        for (int i = 0; i < n; i++) {
          if (!rowCover[i]) {
            for (int j = 0; j < n; j++) {
              if (!colCover[j] && matrix[i][j] < minUncovered) {
                minUncovered = matrix[i][j];
              }
            }
          }
        }
        for (int i = 0; i < n; i++) {
          for (int j = 0; j < n; j++) {
            if (rowCover[i]) matrix[i][j] += minUncovered;
            if (!colCover[j]) matrix[i][j] -= minUncovered;
          }
        }
      }
    }

    // Step 6: Construct series of alternating primed and starred zeros
    List<List<int>> path = [];
    path.add([zeroRow, zeroCol]);
    bool found;
    do {
      found = false;
      int row = path.last[0];
      int col = path.last[1];
      // Find starred zero in this column
      int starRow = -1;
      for (int i = 0; i < n; i++) {
        if (mask[i][col] == 1) {
          starRow = i;
          break;
        }
      }
      if (starRow != -1) {
        path.add([starRow, col]);
        // Find primed zero in this row
        int primeCol = -1;
        for (int j = 0; j < n; j++) {
          if (mask[starRow][j] == 2) {
            primeCol = j;
            break;
          }
        }
        if (primeCol != -1) {
          path.add([starRow, primeCol]);
          found = true;
        }
      }
    } while (found);

    // Augment path: flip stars and primes
    for (var p in path) {
      if (mask[p[0]][p[1]] == 1)
        mask[p[0]][p[1]] = 0;
      else if (mask[p[0]][p[1]] == 2) mask[p[0]][p[1]] = 1;
    }
    // Clear all primes and reset covers
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        if (mask[i][j] == 2) mask[i][j] = 0;
      }
      rowCover[i] = false;
      colCover[i] = false;
    }
    // Cover columns with starred zeros again
    coverColumnsWithStarredZero();
  }

  // Extract assignment and compute cost
  List<int> assignment = List.filled(n, -1);
  int totalCost = 0;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (mask[i][j] == 1) {
        assignment[i] = j;
        totalCost += cost[i][j];
      }
    }
  }
  print('Optimal assignment:');
  for (int i = 0; i < n; i++) {
    print('Row $i assigned to column ${assignment[i]} (cost: ${cost[i][assignment[i]]})');
  }
  print('Total cost: $totalCost');
}

