  const womenNames = ['W', 'X', 'Y', 'Z'];

  // Men's preferences: menPrefs[man][rank] = woman index
  const menPrefs = [
    [0, 1, 2, 3], // A's preferences: W, X, Y, Z
    [2, 0, 1, 3], // B's preferences: Y, W, X, Z
    [1, 2, 3, 0], // C's preferences: X, Y, Z, W
    [0, 2, 3, 1], // D's preferences: W, Y, Z, X
  ];

  // Women's preferences: womenPrefs[woman][rank] = man index
  const womenPrefs = [
    [0, 1, 2, 3], // W's preferences: A, B, C, D
    [2, 1, 0, 3], // X's preferences: C, B, A, D
    [1, 2, 3, 0], // Y's preferences: B, C, D, A
    [0, 1, 2, 3], // Z's preferences: A, B, C, D
  ];

  final n = menPrefs.length;

  // For each woman, create a map from man to her ranking (lower is better)
  List<Map<int, int>> womenRankings = List.generate(
    n,
    (w) => {
      for (int rank = 0; rank < n; rank++) womenPrefs[w][rank]: rank,
    },
  );

  // Each man proposes in order; keep track of next woman to propose to
  List<int> nextProposal = List.filled(n, 0);

  // -1 means free/unmatched
  List<int> womanPartner = List.filled(n, -1); // womanPartner[w] = man
  List<int> manPartner = List.filled(n, -1); // manPartner[m] = woman

  // Initially, all men are free
  List<int> freeMen = List.generate(n, (i) => i);

  while (freeMen.isNotEmpty) {
    int m = freeMen.removeLast();
    // Propose to the next woman on m's list
    int w = menPrefs[m][nextProposal[m]];
    nextProposal[m]++;

    if (womanPartner[w] == -1) {
      // Woman w is free, pair her with m
      womanPartner[w] = m;
      manPartner[m] = w;
    } else {
      int mPrime = womanPartner[w];
      // Does w prefer m over current partner mPrime?
      if (womenRankings[w][m]! < womenRankings[w][mPrime]!) {
        // She prefers m, so mPrime becomes free
        womanPartner[w] = m;
        manPartner[m] = w;
        manPartner[mPrime] = -1;
        freeMen.add(mPrime);
      } else {
        // She stays with mPrime; m remains free
        freeMen.add(m);
      }
    }
  }

  // Print the matches
  print('Stable matches:');
  for (int m = 0; m < n; m++) {
    print('${menNames[m]} is matched with ${womenNames[manPartner[m]]}');
  }
}

