class Point {
  final int x;
  final int y;

  Point(this.x, this.y);

  @override
  String toString() => '($x, $y)';

  // Computes the cross product of vectors OA and OB for points O, A, B
  static int cross(Point o, Point a, Point b) {
    return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
  }

  // Computes the squared distance between two points
  static int dist2(Point a, Point b) {
    int dx = a.x - b.x;
    int dy = a.y - b.y;
    return dx * dx + dy * dy;
  }
}

void main() {
