    Point(0, 3),
    Point(2, 2),
    Point(1, 1),
    Point(2, 1),
    Point(3, 0),
    Point(0, 0),
    Point(3, 3),
  ];

  // Handle cases with 0 or 1 point (trivial convex hull)
  if (points.length <= 1) {
    print('Convex hull: $points');
    return;
  }

  // Step 1: Sort points by y-coordinate (and by x-coordinate in case of tie)
  points.sort((a, b) {
    if (a.y != b.y) {
      return a.y - b.y;
    }
    return a.x - b.x;
  });

  // The point with the smallest y (and leftmost if tie) is the starting point
  Point p0 = points[0];

  // Step 2: Sort the remaining points by polar angle with p0
  // Use a sublist from index 1 to the end, then sort with a custom comparator
  List<Point> sortedRest = points.sublist(1)..sort((a, b) {
    int cp = Point.cross(p0, a, b);
    if (cp == 0) {
      // If collinear, sort by distance from p0 (closer first)
      return Point.dist2(p0, a) - Point.dist2(p0, b);
    }
    // Negative cross product for counter-clockwise order
    return -cp;
  });

  // Reconstruct the points list with p0 first followed by sorted points
  points = [p0] + sortedRest;

  // Step 3: Graham scan to build the convex hull
