    while (hull.length >= 2 && 
           Point.cross(hull[hull.length - 2], hull[hull.length - 1], p) <= 0) {
      hull.removeLast(); // Remove the last point if it makes a non-left turn
    }
    hull.add(p); // Add the current point
  }

