import 'dart:io';
import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Example points (can be replaced with user input or random points)
  List<Point<double>> points = [
    Point(2, 3),
    Point(12, 30),
    Point(40, 50),
    Point(5, 1),
    Point(12, 10),
    Point(3, 4),
  ];

  if (points.length < 2) {
    print('At least two points are required.');
    return;
  }

  // Helper to compute Euclidean distance
  double dist(Point<double> p1, Point<double> p2) =>
      sqrt(pow(p1.x - p2.x, 2) + pow(p1.y - p2.y, 2));

  // Brute force for small sets
  double bruteForce(List<Point<double>> pts, int left, int right) {
    double minDist = double.infinity;
    for (int i = left; i < right; i++) {
      for (int j = i + 1; j < right; j++) {
        double d = dist(pts[i], pts[j]);
        if (d < minDist) minDist = d;
      }
    }
    return minDist;
  }

  // Find the minimal distance in a strip
  double stripClosest(List<Point<double>> strip, double d) {
    double minDist = d;
    strip.sort((a, b) => a.y.compareTo(b.y));
    for (int i = 0; i < strip.length; i++) {
      for (int j = i + 1;
          j < strip.length && (strip[j].y - strip[i].y) < minDist;
          j++) {
        double distVal = dist(strip[i], strip[j]);
        if (distVal < minDist) minDist = distVal;
      }
    }
    return minDist;
  }

  // Recursive closest pair function
  double closestUtil(List<Point<double>> ptsSortedX, int left, int right) {
    if (right - left <= 3) return bruteForce(ptsSortedX, left, right);

    int mid = (left + right) ~/ 2;
    Point<double> midPoint = ptsSortedX[mid];

    double dl = closestUtil(ptsSortedX, left, mid);
    double dr = closestUtil(ptsSortedX, mid, right);

    double d = min(dl, dr);

    List<Point<double>> strip = [];
    for (int i = left; i < right; i++) {
      if ((ptsSortedX[i].x - midPoint.x).abs() < d) {
        strip.add(ptsSortedX[i]);
      }
    }

    return min(d, stripClosest(strip, d));
  }

  // Sort points by x coordinate
  List<Point<double>> ptsSortedX = List.from(points)
    ..sort((a, b) => a.x.compareTo(b.x));

  double minDistance = closestUtil(ptsSortedX, 0, ptsSortedX.length);

  print('The smallest distance is $minDistance');
}

