  const int bitArraySize = 128; // Size of bit array (m)
  const int hashFunctions = 3; // Number of hash functions (k)

  // Bit array as Uint8List for efficiency
  final bitArray = Uint8List((bitArraySize / 8).ceil());

  // Simple hash functions using base hash + salts
  int _hash(String s, int seed) {
    // FNV-1a hash with seed
    const int fnvPrime = 0x01000193;
    int hash = 0x811C9DC5 ^ seed;
    for (var codeUnit in utf8.encode(s)) {
      hash ^= codeUnit;
      hash = (hash * fnvPrime) & 0xFFFFFFFF;
    }
    return hash.abs();
  }

  // Set bit in the bit array
  void _setBit(int bit) {
    final byteIndex = bit >> 3;
    final bitIndex = bit & 7;
    bitArray[byteIndex] |= (1 << bitIndex);
  }

  // Check bit in the bit array
  bool _checkBit(int bit) {
    final byteIndex = bit >> 3;
    final bitIndex = bit & 7;
    return (bitArray[byteIndex] & (1 << bitIndex)) != 0;
  }

  // Add an element to the bloom filter
  void add(String item) {
    for (int i = 0; i < hashFunctions; i++) {
      int hash = _hash(item, i);
      int bit = hash % bitArraySize;
      _setBit(bit);
    }
  }

  // Check membership
  bool contains(String item) {
    for (int i = 0; i < hashFunctions; i++) {
      int hash = _hash(item, i);
      int bit = hash % bitArraySize;
      if (!_checkBit(bit)) return false;
    }
    return true;
  }

  // Demo
  final itemsToAdd = ['apple', 'banana', 'orange', 'grape'];
  for (var item in itemsToAdd) {
    add(item);
    print('Added: $item');
  }

  final testItems = ['apple', 'banana', 'lemon', 'grapefruit', 'orange', 'grape', 'pear'];
