    int idx1 = hash1(key);
    if (table1[idx1] == key) {
      table1[idx1] = null;
      return true;
    }
    int idx2 = hash2(key);
    if (table2[idx2] == key) {
      table2[idx2] = null;
      return true;
    }
    return false;
  }

  // Print both tables
  void printTables() {
    print('Table 1:');
    for (int i = 0; i < tableSize; ++i) {
      print('[$i]: ${table1[i]}');
    }
    print('Table 2:');
    for (int i = 0; i < tableSize; ++i) {
      print('[$i]: ${table2[i]}');
    }
