      // Generate a small random step in [-0.5, 0.5]
      double step = (rand.nextDouble() * 2 - 1) * 0.5;
      double neighbor = current + step;
      // Clamp the neighbor to the bounds [-5, 5]
      neighbor = neighbor.clamp(-5.0, 5.0);

      double delta = objective(neighbor) - objective(current);

      // Metropolis acceptance criterion
      if (delta < 0 || rand.nextDouble() < exp(-delta / temp)) {
        current = neighbor;
        // Update the best solution if improved
        if (objective(current) < bestVal) {
          best = current;
          bestVal = objective(best);
        }
      }
    }
    // Cool down the temperature
    temp *= alpha;
  }

  print('Best found x: $best, f(x): $bestVal');
}
