import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Genetic Algorithm parameters
  const int populationSize = 20;
  const int chromosomeLength = 16; // Number of bits
  const int generations = 50;
  const double mutationRate = 0.01;
  const double crossoverRate = 0.7;

  final Random rand = Random();

  // Fitness function: maximize the number of 1s in the chromosome
  int fitness(List<int> chromosome) => chromosome.fold(0, (a, b) => a + b);

  // Generate a random chromosome
  List<int> randomChromosome() =>
      List<int>.generate(chromosomeLength, (_) => rand.nextBool() ? 1 : 0);

  // Initial population
  List<List<int>> population =
      List<List<int>>.generate(populationSize, (_) => randomChromosome());

  // Tournament selection
  List<int> selectParent(List<List<int>> pop) {
    int a = rand.nextInt(pop.length);
    int b = rand.nextInt(pop.length);
    return fitness(pop[a]) > fitness(pop[b]) ? pop[a] : pop[b];
  }

  // Single-point crossover
  List<List<int>> crossover(List<int> p1, List<int> p2) {
    if (rand.nextDouble() > crossoverRate) {
      // No crossover, return clones
      return [List<int>.from(p1), List<int>.from(p2)];
    }
    int point = rand.nextInt(chromosomeLength - 1) + 1;
    List<int> c1 = List<int>.from(p1.take(point))..addAll(p2.skip(point));
    List<int> c2 = List<int>.from(p2.take(point))..addAll(p1.skip(point));
    return [c1, c2];
  }

  // Mutation
  void mutate(List<int> chromosome) {
    for (int i = 0; i < chromosome.length; i++) {
      if (rand.nextDouble() < mutationRate) {
        chromosome[i] = 1 - chromosome[i];
      }
    }
  }

  for (int gen = 1; gen <= generations; gen++) {
    // Evaluate fitness
    List<int> fitnesses = population.map(fitness).toList();
    int bestFit = fitnesses.reduce(max);
    int bestIdx = fitnesses.indexOf(bestFit);

    print(
        'Generation $gen: Best fitness = $bestFit, Chromosome = ${population[bestIdx].join()}');

    // Next generation
    List<List<int>> newPopulation = [];

    // Elitism: carry the best individual to the next generation
    newPopulation.add(List<int>.from(population[bestIdx]));

    while (newPopulation.length < populationSize) {
      // Selection
      List<int> parent1 = selectParent(population);
      List<int> parent2 = selectParent(population);

      // Crossover
      List<List<int>> offspring = crossover(parent1, parent2);

      // Mutation
      mutate(offspring[0]);
      if (newPopulation.length + 1 < populationSize) {
        mutate(offspring[1]);
        newPopulation.add(offspring[0]);
        newPopulation.add(offspring[1]);
      } else {
        newPopulation.add(offspring[0]);
      }
    }

    population = newPopulation;
  }

  // Final result
  List<int> finalFitnesses = population.map(fitness).toList();
  int bestFinalFit = finalFitnesses.reduce(max);
  int bestFinalIdx = finalFitnesses.indexOf(bestFinalFit);
  print('\nBest solution after $generations generations:');
  print('Fitness = $bestFinalFit');
  print('Chromosome = ${population[bestFinalIdx].join()}');
}

