  // List to permute
  List<int> nums = [1, 2, 3];

  // Store all permutations
  List<List<int>> results = [];

  // Helper backtracking function
  void backtrack(List<int> path, List<bool> used) {
    if (path.length == nums.length) {
      results.add(List.from(path));
      return;
    }
    for (int i = 0; i < nums.length; i++) {
      if (used[i]) continue;
      used[i] = true;
      path.add(nums[i]);
      backtrack(path, used);
      path.removeLast();
      used[i] = false;
    }
  }

  backtrack([], List.filled(nums.length, false));

  // Print all permutations
  for (var perm in results) {
    print(perm);
  }
}

