void main() {
  const int width = 20;
  const int height = 10;

  // Directions: (dx, dy, wall bit)
  final dirs = [
    [0, -1, 1], // Up
    [1, 0, 2],  // Right
    [0, 1, 4],  // Down
    [-1, 0, 8], // Left
  ];
  final opposite = {1: 4, 2: 8, 4: 1, 8: 2};

  // Each cell: 0 = all walls, bits: 1=up,2=right,4=down,8=left
  List<List<int>> maze = List.generate(height, (_) => List.filled(width, 0));
  List<List<bool>> visited = List.generate(height, (_) => List.filled(width, false));
  Random rand = Random();

  void dfs(int x, int y) {
    visited[y][x] = true;
    var dirOrder = List.generate(4, (i) => i)..shuffle(rand);
    for (var i in dirOrder) {
      int dx = dirs[i][0], dy = dirs[i][1], wall = dirs[i][2];
      int nx = x + dx, ny = y + dy;
      if (ny >= 0 && ny < height && nx >= 0 && nx < width && !visited[ny][nx]) {
        maze[y][x] |= wall;
        maze[ny][nx] |= opposite[wall]!;
        dfs(nx, ny);
      }
    }
  }

  dfs(0, 0);

  // Print maze as ASCII
  // Top border
  StringBuffer sb = StringBuffer();
  sb.write('┏');
  for (int x = 0; x < width; x++) {
    sb.write('━━');
    sb.write(x == width - 1 ? '┓\n' : '┳');
  }
  for (int y = 0; y < height; y++) {
    // Left wall
    sb.write('┃');
    for (int x = 0; x < width; x++) {
      sb.write(' ');
      // Right wall
      sb.write((maze[y][x] & 2) != 0 ? ' ' : '┃');
    }
    sb.write('\n');
    // Bottom wall or passage
    if (y == height - 1) break;
    sb.write('┣');
    for (int x = 0; x < width; x++) {
      sb.write((maze[y][x] & 4) != 0 ? '  ' : '━━');
      sb.write(x == width - 1 ? '┫\n' : (maze[y][x] & 4) != 0 ? '╋' : '┻');
    }
  }
  // Bottom border
  sb.write('┗');
  for (int x = 0; x < width; x++) {
    sb.write('━━');
    sb.write(x == width - 1 ? '┛\n' : '┻');
  }
  print(sb.toString());
}

