  print('\nTesting perceptron on AND logic:');
  for (int i = 0; i < X.length; i++) {
    double linear = w[0] * X[i][0] + w[1] * X[i][1] + b;
    int pred = activation(linear);
    print('Input: ${X[i]} -> Predicted: $pred, Target: ${y[i]}');
  }
