import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Example user-item ratings matrix (0 means unrated)
  // Rows: users, Columns: items
  List<List<double>> ratings = [
    [5, 3, 0, 1],
    [4, 0, 0, 1],
    [1, 1, 0, 5],
    [0, 0, 5, 4],
    [1, 0, 4, 0],
  ];

  // Number of users and items
  int numUsers = ratings.length;
  int numItems = ratings[0].length;

  // Compute user similarity (cosine similarity)
  double userSimilarity(int u1, int u2) {
    double dot = 0.0, norm1 = 0.0, norm2 = 0.0;
    for (int i = 0; i < numItems; i++) {
      dot += ratings[u1][i] * ratings[u2][i];
      norm1 += pow(ratings[u1][i], 2);
      norm2 += pow(ratings[u2][i], 2);
    }
    if (norm1 == 0 || norm2 == 0) return 0.0;
    return dot / (sqrt(norm1) * sqrt(norm2));
  }

  // Predict rating of user u for item i (user-based collaborative filtering)
  double predictRating(int u, int i, {int k = 2}) {
    // Find top-k similar users who have rated item i
    List<MapEntry<int, double>> sims = [];
    for (int v = 0; v < numUsers; v++) {
      if (v != u && ratings[v][i] > 0) {
        double sim = userSimilarity(u, v);
        sims.add(MapEntry(v, sim));
      }
    }
    sims.sort((a, b) => b.value.compareTo(a.value));
    sims = sims.take(k).toList();

    // Weighted sum of ratings
    double num = 0.0, denom = 0.0;
    for (var entry in sims) {
      int v = entry.key;
      double sim = entry.value;
      num += sim * ratings[v][i];
      denom += sim.abs();
    }
    if (denom == 0) return 0.0;
    return num / denom;
  }

  // Recommend items for a given user
  void recommend(int user) {
    print("Recommendations for User $user:");
    for (int i = 0; i < numItems; i++) {
      if (ratings[user][i] == 0) {
        double pred = predictRating(user, i);
        print("  Item $i: Predicted rating = ${pred.toStringAsFixed(2)}");
      }
    }
  }

  // Example: Recommend items for all users
  for (int u = 0; u < numUsers; u++) {
    recommend(u);
  }
}

