  ];

  double minSupport = 0.4; // minimum support threshold (e.g., 40%)
  double minConfidence = 0.7; // minimum confidence threshold (e.g., 70%)

  int minSupportCount = (minSupport * transactions.length).ceil();

  // Step 1: Generate frequent itemsets
  Map<int, List<Set<String>>> frequentItemsets = {};
  Map<Set<String>, int> supportCount = {};

  // 1-itemsets
  Map<String, int> itemCount = {};
  for (var transaction in transactions) {
    for (var item in transaction) {
      itemCount[item] = (itemCount[item] ?? 0) + 1;
    }
  }
  List<Set<String>> L1 = [];
  for (var entry in itemCount.entries) {
    if (entry.value >= minSupportCount) {
      var itemset = {entry.key};
      L1.add(itemset);
      supportCount[itemset] = entry.value;
    }
  }
  frequentItemsets[1] = L1;

  int k = 2;
  while (true) {
    List<Set<String>> prevL = frequentItemsets[k - 1]!;
    if (prevL.isEmpty) break;

    // Candidate generation (Apriori-gen)
    Set<Set<String>> candidates = {};
    for (int i = 0; i < prevL.length; i++) {
      for (int j = i + 1; j < prevL.length; j++) {
        var l1 = prevL[i];
        var l2 = prevL[j];
        var union = l1.union(l2);
        if (union.length == k) {
          // Prune: all (k-1)-subsets must be frequent
          bool allSubsetsFrequent = true;
          for (var item in union) {
            var subset = Set<String>.from(union);
            subset.remove(item);
            if (!prevL.contains(subset)) {
              allSubsetsFrequent = false;
              break;
            }
          }
          if (allSubsetsFrequent) {
            candidates.add(union);
          }
        }
      }
    }

    // Count support
    Map<Set<String>, int> candidateCount = {};
    for (var transaction in transactions) {
      for (var candidate in candidates) {
        if (candidate.difference(transaction).isEmpty) {
          candidateCount[candidate] = (candidateCount[candidate] ?? 0) + 1;
        }
      }
    }

    // Select frequent itemsets
    List<Set<String>> Lk = [];
    for (var entry in candidateCount.entries) {
      if (entry.value >= minSupportCount) {
        Lk.add(entry.key);
        supportCount[entry.key] = entry.value;
      }
    }
    if (Lk.isEmpty) break;
    frequentItemsets[k] = Lk;
    k++;
  }

  // Print all frequent itemsets
  print('Frequent itemsets (min support: $minSupport):');
  for (var entry in frequentItemsets.entries) {
    for (var itemset in entry.value) {
      double sup = supportCount[itemset]! / transactions.length;
      print('${itemset.toList()} (support: ${sup.toStringAsFixed(2)})');
    }
  }

  // Step 2: Generate association rules
  print('\nAssociation Rules (min confidence: $minConfidence):');
  for (var entry in frequentItemsets.entries) {
    if (entry.key < 2) continue; // Only itemsets with size >= 2
    for (var itemset in entry.value) {
      var itemsetSupport = supportCount[itemset]!;
      var items = itemset.toList();
      int n = items.length;
      // Generate all non-empty proper subsets
      for (int i = 1; i < (1 << n) - 1; i++) {
        Set<String> antecedent = {};
        Set<String> consequent = {};
        for (int j = 0; j < n; j++) {
          if ((i & (1 << j)) != 0) {
            antecedent.add(items[j]);
          } else {
            consequent.add(items[j]);
          }
        }
        if (antecedent.isEmpty || consequent.isEmpty) continue;
        int antecedentSupport = supportCount[antecedent] ?? 0;
        if (antecedentSupport == 0) continue;
        double confidence = itemsetSupport / antecedentSupport;
        if (confidence >= minConfidence) {
          double support = itemsetSupport / transactions.length;
          print('${antecedent.toList()} => ${consequent.toList()} (support: ${support.toStringAsFixed(2)}, confidence: ${confidence.toStringAsFixed(2)})');
        }
      }
    }
  }
}

