    [1.0, 2.0],
    [1.5, 1.8],
    [5.0, 8.0],
    [8.0, 8.0],
    [1.0, 0.6],
    [9.0, 11.0],
    [8.0, 2.0],
    [10.0, 2.0],
    [9.0, 3.0],
  ];

  // Each cluster is a list of point indices
  List<List<int>> clusters = List.generate(data.length, (i) => [i]);

  // Compute Euclidean distance between two points
  double dist(int i, int j) {
    double sum = 0.0;
    for (int d = 0; d < data[i].length; d++) {
      sum += pow(data[i][d] - data[j][d], 2);
    }
    return sqrt(sum);
  }

  // Compute distance between two clusters using single linkage (minimum distance between any points)
  double clusterDist(List<int> a, List<int> b) {
    double minDist = double.infinity;
    for (var i in a) {
      for (var j in b) {
        if (i != j) { // Avoid unnecessary self-comparison if clusters share points, but in this case, initial clusters don't
          double d = dist(i, j);
          if (d < minDist) {
            minDist = d;
          }
        }
      }
    }
    return minDist;
  }

  print('Initial clusters:');
  print(clusters);

  // Agglomerative clustering loop
  while (clusters.length > 1) {
    double minDistance = double.infinity;
    int mergeA = -1;
    int mergeB = -1;

    // Find the closest pair of clusters
    for (int i = 0; i < clusters.length; i++) {
      for (int j = i + 1; j < clusters.length; j++) {
        double d = clusterDist(clusters[i], clusters[j]);
        if (d < minDistance) {
          minDistance = d;
          mergeA = i;
          mergeB = j;
        }
      }
    }

    // Merge the closest clusters if found
    if (mergeA != -1 && mergeB != -1) {
      clusters[mergeA] = [...clusters[mergeA], ...clusters[mergeB]]; // Combine the clusters
      clusters.removeAt(mergeB); // Remove the merged cluster
      print('Merged clusters $mergeA and $mergeB at distance $minDistance');
      print('Clusters: $clusters');
    } else {
      break; // Safety break if no merge found (unlikely in practice)
    }
  }

  // Output the final cluster
  print('\nFinal cluster:');
  print(clusters);
}
