void main() {
  // A sync* generator that yields the first n Fibonacci numbers.
  Iterable<int> fibonacci(int n) sync* {
    int a = 0, b = 1;
    for (int i = 0; i < n; i++) {
      yield a;
      int next = a + b;
      a = b;
      b = next;
    }
  }

  // A sync* generator that yields the squares of numbers up to n.
  Iterable<int> squares(int n) sync* {
    for (int i = 1; i <= n; i++) {
      yield i * i;
    }
  }

  // Using the fibonacci generator
  print('First 10 Fibonacci numbers:');
  for (var num in fibonacci(10)) {
    print(num);
  }

  // Using the squares generator
  print('\nSquares up to 5:');
  for (var sq in squares(5)) {
    print(sq);
  }
}

