void main() {
  // Define a Unicode string with emojis and accented characters
  String text = 'Dart 💙 — Привет мир! 你好世界! àéîöü';

  // Print the original string
  print('Original string: $text');

  // Print the number of runes (Unicode code points) in the string
  print('Number of characters (runes): ${text.runes.length}');

  // Print each rune's code point and the corresponding character
  print('Individual runes (code points):');
  for (var rune in text.runes) {
    // Convert the code point to a character
    String char = String.fromCharCode(rune);
    // Format the code point as uppercase hexadecimal with padding
    print('U+${rune.toRadixString(16).toUpperCase().padLeft(4, "0")} : $char');
  }

  // Convert the runes to a list for further manipulation
  List<int> runeList = text.runes.toList();

  // Extract the emoji at position 5 (after "Dart ")
  int emojiStart = 5;
  int emojiLength = 1;
  String emoji = String.fromCharCodes(runeList.sublist(emojiStart, emojiStart + emojiLength));
  print('Extracted emoji: $emoji');

  // Reverse the string by reversing the list of runes
  String reversed = String.fromCharCodes(text.runes.toList().reversed);
  print('Reversed string (by runes): $reversed');
}
```

### Explanation:
- **Original String Handling**: The string `text` contains various Unicode characters, and it is printed directly.
- **Rune Counting**: The `runes.length` property is used to get the number of Unicode code points, which may differ from the number of code units for strings with emojis or complex characters.
