      Datagram? dg = socket.receive();
      if (dg != null) {
        print('Received from ${dg.address.address}:${dg.port}: ${String.fromCharCodes(dg.data)}');
      }
    }
  });

  // Wait for 5 seconds before closing the socket
  await Future.delayed(Duration(seconds: 5));
