          .replaceAll(r'\', r'\\')
          .replaceAll('"', r'\"')
          .replaceAll('\b', r'\b')
          .replaceAll('\f', r'\f')
          .replaceAll('\n', r'\n')
          .replaceAll('\r', r'\r')
