  BigInt diff = a - b;
  BigInt prod = a * b;
  BigInt? quot;
  BigInt? rem;
  if (b != BigInt.zero) {
    quot = a ~/ b;
    rem = a.remainder(b);
  }

  print('\nResults:');
  print('a + b = $sum');
  print('a - b = $diff');
  print('a * b = $prod');
  if (b != BigInt.zero) {
    print('a ~/ b = $quot');
    print('a % b = $rem');
  } else {
    print('Division by zero is not allowed.');
  }

  // Exponentiation (to a small power)
