import 'dart:math';

class Complex {
  final double re;
  final double im;

  const Complex(this.re, this.im);

  Complex operator +(Complex other) => Complex(re + other.re, im + other.im);

  Complex operator -(Complex other) => Complex(re - other.re, im - other.im);

  Complex operator *(Complex other) =>
      Complex(re * other.re - im * other.im, re * other.im + im * other.re);

  Complex operator /(Complex other) {
    final denom = other.re * other.re + other.im * other.im;
    if (denom == 0) throw ArgumentError('Division by zero');
    return Complex(
      (re * other.re + im * other.im) / denom,
      (im * other.re - re * other.im) / denom,
    );
  }

  double abs() => sqrt(re * re + im * im);

  double arg() => atan2(im, re);

  Complex conjugate() => Complex(re, -im);

  @override
  String toString() {
    String sign = im >= 0 ? '+' : '-';
    return '${re.toStringAsFixed(2)} $sign ${im.abs().toStringAsFixed(2)}i';
  }
}

@pragma('vm:entry-point')
void main() {
  // Create two complex numbers
  Complex a = Complex(3, 4);
  Complex b = Complex(1, -2);

  print('a = $a');
  print('b = $b');

  // Addition
  Complex sum = a + b;
  print('a + b = $sum');

  // Subtraction
  Complex diff = a - b;
  print('a - b = $diff');

  // Multiplication
  Complex prod = a * b;
  print('a * b = $prod');

  // Division
  Complex quot = a / b;
  print('a / b = $quot');

  // Absolute value (modulus)
  print('|a| = ${a.abs().toStringAsFixed(2)}');

  // Argument (phase)
  print('arg(a) = ${a.arg().toStringAsFixed(2)} radians');

  // Conjugate
  print('conj(a) = ${a.conjugate()}');
}

