    double denominator = other.real * other.real + other.imag * other.imag;
    double r = (real * other.real + imag * other.imag) / denominator;
    double i = (imag * other.real - real * other.imag) / denominator;
    return Complex(r, i);
  }

  double abs() => sqrt(real * real + imag * imag);

  double arg() => atan2(imag, real);

  Complex conjugate() => Complex(real, -imag);

  @override
  String toString() {
    if (imag >= 0) {
      return '$real + ${imag}i';
    } else {
