  // Print enum annotation
  final enumMirror = Weekday;
  final enumDescription = _getEnumDescription(enumMirror);
  print('Enum annotation: $enumDescription\n');

  // Print value annotations
  for (var value in Weekday.values) {
    final annotation = _getEnumValueDescription(value);
    print('${value.name}: $annotation');
  }
