abstract class Animal {
  void makeSound();
  String getName();
}

abstract class Swimmer {
  void swim();
}

class Duck implements Animal, Swimmer {
  @override
  void makeSound() {
    print('Quack!');
  }

  @override
  String getName() {
    return 'Duck';
  }

  @override
  void swim() {
    print('Duck is swimming.');
  }
}

class Dog implements Animal {
  @override
  void makeSound() {
    print('Woof!');
  }

  @override
  String getName() {
    return 'Dog';
  }
}

@pragma('vm:entry-point')
void main() {
  List<Animal> animals = [Duck(), Dog()];

  for (var animal in animals) {
    print('This is a ${animal.getName()}:');
    animal.makeSound();
    if (animal is Swimmer) {
      (animal as Swimmer).swim();
    } else {
      print('${animal.getName()} cannot swim.');
    }
    print('---');
  }
}

