import 'dart:io';

class Message {
  final String sender;
  final String recipient;
  final String content;
  final DateTime timestamp;

  Message(this.sender, this.recipient, this.content)
      : timestamp = DateTime.now();

  @override
  String toString() {
    return '[$timestamp] $sender to $recipient: $content';
  }
}

class User {
  final String username;
  final List<Message> inbox = [];

  User(this.username);

  void receiveMessage(Message message) {
    inbox.add(message);
  }

  void showInbox() {
    if (inbox.isEmpty) {
      print('Inbox is empty.');
    } else {
      for (var msg in inbox) {
        print(msg);
      }
    }
  }
}

class InAppMessagingSystem {
  final Map<String, User> users = {};

  void registerUser(String username) {
    if (users.containsKey(username)) {
      print('User "$username" already exists.');
    } else {
      users[username] = User(username);
      print('User "$username" registered.');
    }
  }

  void sendMessage(String sender, String recipient, String content) {
    if (!users.containsKey(sender)) {
      print('Sender "$sender" does not exist.');
      return;
    }
    if (!users.containsKey(recipient)) {
      print('Recipient "$recipient" does not exist.');
      return;
    }
    var message = Message(sender, recipient, content);
    users[recipient]!.receiveMessage(message);
    print('Message sent from "$sender" to "$recipient".');
  }

  void showInbox(String username) {
    if (!users.containsKey(username)) {
      print('User "$username" does not exist.');
      return;
    }
    print('Inbox for "$username":');
    users[username]!.showInbox();
  }
}

@pragma('vm:entry-point')
void main() {
  final system = InAppMessagingSystem();

  while (true) {
    print('\n=== In-App Messaging System ===');
    print('1. Register user');
    print('2. Send message');
    print('3. Show inbox');
    print('4. Exit');
    stdout.write('Choose an option: ');
    var input = stdin.readLineSync();
    if (input == null) continue;

    switch (input.trim()) {
      case '1':
        stdout.write('Enter username to register: ');
        var username = stdin.readLineSync();
        if (username != null && username.trim().isNotEmpty) {
          system.registerUser(username.trim());
        } else {
          print('Invalid username.');
        }
        break;
      case '2':
        stdout.write('Sender username: ');
        var sender = stdin.readLineSync();
        stdout.write('Recipient username: ');
        var recipient = stdin.readLineSync();
        stdout.write('Message content: ');
        var content = stdin.readLineSync();
        if (sender != null &&
            recipient != null &&
            content != null &&
            sender.trim().isNotEmpty &&
            recipient.trim().isNotEmpty &&
            content.trim().isNotEmpty) {
          system.sendMessage(sender.trim(), recipient.trim(), content.trim());
        } else {
          print('Invalid input.');
        }
        break;
      case '3':
        stdout.write('Enter username to view inbox: ');
        var username = stdin.readLineSync();
        if (username != null && username.trim().isNotEmpty) {
          system.showInbox(username.trim());
        } else {
          print('Invalid username.');
        }
        break;
      case '4':
        print('Exiting...');
        return;
      default:
        print('Invalid option.');
    }
  }
}

