    print('No cache found. Fetching from API...');
    final data = await fetchDataFromApi();
    print('Fetched data:');
    print(data);
    await saveToCache(data);
  }
}

import 'dart:io';
import 'dart:math';

/// A simple data model for a place of interest.
class Place {
  final String name;
  final double latitude;
  final double longitude;

  Place(this.name, this.latitude, this.longitude);
}

/// Computes the distance in kilometers between two latitude/longitude points using the Haversine formula.
double haversine(double lat1, double lon1, double lat2, double lon2) {
  const earthRadius = 6371; // Earth's radius in kilometers
  final dLat = _degToRad(lat2 - lat1);
  final dLon = _degToRad(lon2 - lon1);

  final a = sin(dLat / 2) * sin(dLat / 2) +
      cos(_degToRad(lat1)) *
          cos(_degToRad(lat2)) *
          sin(dLon / 2) *
          sin(dLon / 2);
  final c = 2 * atan2(sqrt(a), sqrt(1 - a));
  return earthRadius * c;
}

double _degToRad(double deg) => deg * pi / 180;

/// Sample places of interest.
final List<Place> places = [
  Place('Central Park', 40.785091, -73.968285),
  Place('Empire State Building', 40.748817, -73.985428),
  Place('Statue of Liberty', 40.689247, -74.044502),
  Place('Times Square', 40.758896, -73.985130),
  Place('Brooklyn Bridge', 40.706086, -73.996864),
];

@pragma('vm:entry-point')
void main() async {
  print('Welcome to GeoService!');
  stdout.write('Enter your latitude: ');
  final latInput = stdin.readLineSync();
  stdout.write('Enter your longitude: ');
  final lonInput = stdin.readLineSync();

  if (latInput == null ||
      lonInput == null ||
      latInput.isEmpty ||
      lonInput.isEmpty) {
    print('Invalid input. Exiting.');
    return;
  }

  final double? userLat = double.tryParse(latInput);
  final double? userLon = double.tryParse(lonInput);

  if (userLat == null || userLon == null) {
    print('Invalid coordinates. Exiting.');
    return;
  }

  // Find the nearest place
  Place? nearest;
  double minDistance = double.infinity;

  for (final place in places) {
    final dist = haversine(userLat, userLon, place.latitude, place.longitude);
    if (dist < minDistance) {
      minDistance = dist;
      nearest = place;
    }
  }

  print('\nNearby Places (within 5km):');
  bool anyNearby = false;
  for (final place in places) {
    final dist = haversine(userLat, userLon, place.latitude, place.longitude);
    if (dist <= 5) {
      print('- ${place.name} (${dist.toStringAsFixed(2)} km away)');
      anyNearby = true;
    }
  }
  if (!anyNearby) {
    print('No places found within 5km.');
  }

  if (nearest != null) {
    print(
        '\nThe nearest place is ${nearest.name}, which is ${minDistance.toStringAsFixed(2)} km away.');
  }
}

