import 'dart:convert';
import 'dart:io';

/// Simple in-app analytics tracker.
class AnalyticsTracker {
  final List<Map<String, dynamic>> _events = [];

  /// Tracks a generic event with a name and optional properties.
  void trackEvent(String eventName, [Map<String, dynamic>? properties]) {
    final event = <String, dynamic>{
      'event': eventName,
      'timestamp': DateTime.now().toIso8601String(),
      if (properties != null) ...properties,
    };
    _events.add(event);
    print('Tracked event: ${jsonEncode(event)}');
  }

  /// Returns all tracked events.
  List<Map<String, dynamic>> get events => List.unmodifiable(_events);

  /// Simulates sending analytics data to a server.
  Future<void> flush() async {
    print('\nFlushing analytics data to server...');
    // Simulate network delay
    await Future.delayed(Duration(seconds: 1));
    print('Analytics payload:');
    print(jsonEncode(_events));
    print('Flush complete.\n');
    _events.clear();
  }
}

@pragma('vm:entry-point')
void main() async {
  final analytics = AnalyticsTracker();

  // Simulate app start
  analytics.trackEvent('app_open');

  // Simulate user viewing a page
  analytics.trackEvent('page_view', {'page': 'home'});

  // Simulate user clicking a button
  analytics.trackEvent('button_click', {'button_id': 'signup', 'location': 'home_hero'});

  // Simulate user completing an action
  analytics.trackEvent('signup_complete', {'user_id': 'user_1234'});

  // Simulate app going to background
  analytics.trackEvent('app_background');

  // Flush analytics data (send to server)
  await analytics.flush();

  // Simulate more events after flush
  analytics.trackEvent('app_foreground');
  analytics.trackEvent('page_view', {'page': 'profile'});

  // Final flush before exit
  await analytics.flush();

  print('Analytics tracking session complete.');
}

