  // Social platforms
  final platforms = <String, String>{
    '1': 'Twitter',
    '2': 'Facebook',
    '3': 'LinkedIn',
    '4': 'WhatsApp',
    '5': 'Reddit',
    '6': 'Copy Link',
    '0': 'Exit',
  };

  // Print social sharing menu
  void printMenu() {
    print('\n=== Share This Article ===');
    platforms.forEach((key, value) {
      print('[$key] $value');
    });
    print('Choose a platform to share:');
  }

  // Generate sharing URLs
  String getShareUrl(String platform) {
    final encodedUrl = Uri.encodeComponent(contentUrl);
    final encodedTitle = Uri.encodeComponent(contentTitle);
    switch (platform) {
      case 'Twitter':
        return 'https://twitter.com/intent/tweet?url=$encodedUrl&text=$encodedTitle';
      case 'Facebook':
        return 'https://www.facebook.com/sharer/sharer.php?u=$encodedUrl';
      case 'LinkedIn':
        return 'https://www.linkedin.com/sharing/share-offsite/?url=$encodedUrl';
      case 'WhatsApp':
        return 'https://wa.me/?text=$encodedTitle%20$encodedUrl';
      case 'Reddit':
        return 'https://www.reddit.com/submit?url=$encodedUrl&title=$encodedTitle';
      case 'Copy Link':
        return contentUrl;
      default:
        return '';
    }
  }

  // Simulate copying to clipboard (just prints to terminal)
  void copyToClipboard(String text) {
    print('\n[Copied to clipboard]: $text\n');
