    final platform = platforms[input];
    if (platform == null) {
      print('Invalid selection. Please try again.');
      continue;
    }
    final shareUrl = getShareUrl(platform);
    if (platform == 'Copy Link') {
      copyToClipboard(shareUrl);
    } else {
      print('\nOpen this URL to share on $platform:\n$shareUrl\n');
    }
  }
}

