/// Simulate an API endpoint for form submission.
Future<bool> submitFormOnline(Map<String, String> formData) async {
  // Simulate network delay
  await Future.delayed(Duration(seconds: 2));
  // Simulate network status: 50% chance of being online
  final online = DateTime.now().second % 2 == 0;
  if (online) {
    print('Form submitted online: $formData');
    return true;
  } else {
    print('Network unavailable. Submission failed.');
    return false;
  }
}

/// Save form data locally for later submission.
Future<void> saveFormOffline(Map<String, String> formData) async {
  final file = File('offline_forms.json');
  List<dynamic> forms = [];
  if (await file.exists()) {
    final content = await file.readAsString();
    if (content.isNotEmpty) {
      forms = jsonDecode(content);
    }
  }
  forms.add(formData);
  await file.writeAsString(jsonEncode(forms));
  print('Form saved offline.');
}

/// Try to resubmit all offline forms if network is available.
Future<void> tryResubmitOfflineForms() async {
  final file = File('offline_forms.json');
  if (!await file.exists()) return;
  final content = await file.readAsString();
  if (content.isEmpty) return;
  List<dynamic> forms = jsonDecode(content);
  List<dynamic> remaining = [];
  for (var form in forms) {
    final success = await submitFormOnline(Map<String, String>.from(form));
    if (!success) {
      remaining.add(form);
    }
  }
  if (remaining.isEmpty) {
    await file.delete();
    print('All offline forms resubmitted successfully.');
  } else {
    await file.writeAsString(jsonEncode(remaining));
    print('${remaining.length} form(s) still offline.');
  }
}

