import 'dart:io';
import 'dart:async';
import 'dart:convert';

@pragma('vm:entry-point')
Future<void> main() async {
  stdout.writeln('Dart File Download Manager');
  stdout.writeln('-------------------------');
  stdout.write('Enter the file URL to download: ');
  final url = stdin.readLineSync();

  if (url == null || url.isEmpty) {
    stdout.writeln('No URL provided. Exiting.');
    return;
  }

  Uri? uri;
  try {
    uri = Uri.parse(url);
    if (!uri.hasScheme || !(uri.isScheme('http') || uri.isScheme('https'))) {
      throw FormatException('Invalid URL scheme.');
    }
  } catch (e) {
    stdout.writeln('Invalid URL: $e');
    return;
  }

  String? filename;
  // Try to extract filename from URL
  var segments = uri.pathSegments;
  if (segments.isNotEmpty && segments.last.isNotEmpty) {
    filename = segments.last;
  } else {
    filename = 'downloaded_file';
  }
  // Prompt user to override filename
  stdout.write('Enter the filename to save as [$filename]: ');
  final inputName = stdin.readLineSync();
  if (inputName != null && inputName.trim().isNotEmpty) {
    filename = inputName.trim();
  }

  final file = File(filename);

  final client = HttpClient();
  IOSink? fileSink;
  try {
    stdout.writeln('Starting download...');
    final request = await client.getUrl(uri);
    final response = await request.close();

    if (response.statusCode != 200) {
      stdout.writeln('Failed to download file. HTTP status: ${response.statusCode}');
      return;
    }

    final contentLength = response.contentLength;
    int received = 0;
    int lastPercent = -1;

    fileSink = file.openWrite();

    await response.listen(
      (data) {
        fileSink!.add(data);
        received += data.length;
        if (contentLength > 0) {
          final percent = ((received / contentLength) * 100).toInt();
          if (percent != lastPercent) {
            stdout.write('\rProgress: $percent%');
            lastPercent = percent;
          }
        } else {
          stdout.write('\rDownloaded ${received ~/ 1024} KB');
        }
      },
      onDone: () async {
        await fileSink!.flush();
        await fileSink.close();
        stdout.writeln('\nDownload complete. Saved as "$filename".');
        client.close();
      },
      onError: (e) async {
        await fileSink?.close();
        stdout.writeln('\nError during download: $e');
        client.close();
      },
      cancelOnError: true,
    ).asFuture();
  } catch (e) {
    await fileSink?.close();
    stdout.writeln('\nAn error occurred: $e');
    client.close();
  }
}

import 'dart:async';
import 'dart:convert';
import 'dart:math';

/// Simulated device class
class Device {
  final String id;
  Map<String, dynamic> data;
  DateTime lastSync;
  final StreamController<SyncMessage> _outbox = StreamController.broadcast();
  final List<StreamSubscription> _subscriptions = [];

  Device(this.id, this.data)
      : lastSync = DateTime.now();

  Stream<SyncMessage> get outbox => _outbox.stream;

  void connectTo(Device other) {
    // Listen to other's outbox and handle incoming sync messages
    _subscriptions.add(
      other.outbox.listen((msg) {
        if (msg.toId == id) {
          _handleSync(msg);
        }
      }),
    );
  }

  void disconnect() {
    for (var sub in _subscriptions) {
      sub.cancel();
    }
    _subscriptions.clear();
  }

  void updateData(String key, dynamic value) {
    data[key] = value;
    lastSync = DateTime.now();
    print('[$id] Updated data: $key = $value');
  }

  void sendSync(String toId) {
    var msg = SyncMessage(
      fromId: id,
      toId: toId,
      payload: Map<String, dynamic>.from(data),
      timestamp: lastSync,
    );
    _outbox.add(msg);
    print('[$id] Sent sync to $toId: ${jsonEncode(msg.payload)}');
  }

  void _handleSync(SyncMessage msg) {
    // Simple conflict resolution: latest timestamp wins
    bool updated = false;
    msg.payload.forEach((key, value) {
      if (!data.containsKey(key) ||
          msg.timestamp.isAfter(lastSync)) {
        data[key] = value;
        updated = true;
      }
    });
    if (updated) {
      lastSync = msg.timestamp;
      print('[$id] Synced from ${msg.fromId}: ${jsonEncode(data)}');
    }
  }
}

/// Message representing a data sync between devices
class SyncMessage {
  final String fromId;
  final String toId;
  final Map<String, dynamic> payload;
  final DateTime timestamp;

  SyncMessage({
    required this.fromId,
    required this.toId,
    required this.payload,
    required this.timestamp,
  });
}

