import 'dart:convert';
import 'dart:io';

@pragma('vm:entry-point')
void main() async {
  // Example data: List of maps (rows)
  final List<Map<String, dynamic>> data = [
    {'Name': 'Alice', 'Age': 30, 'City': 'New York'},
    {'Name': 'Bob', 'Age': 25, 'City': 'Los Angeles'},
    {'Name': 'Charlie', 'Age': 35, 'City': 'Chicago'},
  ];

  // Extract headers
  final headers = data.isNotEmpty ? data.first.keys.toList() : <String>[];

  // Prepare CSV lines
  List<List<String>> csvRows = [];

  // Add header row
  csvRows.add(headers);

  // Add data rows
  for (var row in data) {
    csvRows.add(headers.map((h) => '${row[h]}').toList());
  }

  // Convert to CSV string with proper escaping
  String toCsv(List<List<String>> rows) {
    // Escape double quotes and surround values containing commas or quotes with double quotes
    String escape(String field) {
      if (field.contains('"')) {
        field = field.replaceAll('"', '""');
      }
      if (field.contains(',') || field.contains('"') || field.contains('\n')) {
        field = '"$field"';
      }
      return field;
    }

    return rows.map((row) => row.map(escape).join(',')).join('\n');
  }

  final csvString = toCsv(csvRows);

  // Write to a file
  final file = File('output.csv');
  await file.writeAsString(csvString, encoding: utf8);

  print('CSV export completed: ${file.path}');
}

