/// This script demonstrates basic accessibility features for a CLI Dart app,
/// simulating screen reader output by printing descriptive text for interactive elements.
/// In a real-world GUI app, you'd use the `semanticsLabel` and accessibility APIs.
/// Here, we simulate by always providing clear, descriptive console output.

@pragma('vm:entry-point')
void main() {
  // Simulated accessible menu
  final menuOptions = [
    'Show current date and time',
    'Display a motivational quote',
    'Exit the program',
  ];

  // Print accessible app title
  print('=== Accessible CLI Demo ===');
  print('This application is designed with accessibility in mind.');
  print('Screen reader: Main menu loaded.');
  print('');

  while (true) {
    // Print accessible menu options
    print('Please select an option by entering the number:');
    for (var i = 0; i < menuOptions.length; i++) {
      print('  ${i + 1}. ${menuOptions[i]}');
    }

    stdout.write('Enter your choice (1-${menuOptions.length}): ');
    String? input = stdin.readLineSync();

    if (input == null) {
      print('Screen reader: No input detected. Please try again.');
      continue;
    }

    int? choice = int.tryParse(input);
    if (choice == null || choice < 1 || choice > menuOptions.length) {
      print('Screen reader: Invalid choice. Please enter a number from 1 to ${menuOptions.length}.');
      continue;
    }

    print('Screen reader: You selected "${menuOptions[choice - 1]}".');

    switch (choice) {
      case 1:
        final now = DateTime.now();
        print('Current date and time: ${now.toLocal()}');
        print('Screen reader: Displayed current date and time.');
        break;
      case 2:
        final quote = 'The only way to do great work is to love what you do. - Steve Jobs';
        print('Motivational quote: "$quote"');
        print('Screen reader: Displayed a motivational quote.');
        break;
      case 3:
        print('Screen reader: Exiting the program. Goodbye!');
        exit(0);
    }
    print(''); // Blank line for spacing
  }
}

