    print('3. Delete Preference');
    print('4. Exit');
    stdout.write('Choose an option (1-4): ');
    final input = stdin.readLineSync();

    if (input == '1') {
      if (prefs.isEmpty) {
        print('No preferences saved.');
      } else {
        print('Current Preferences:');
        prefs.forEach((key, value) {
          print('  $key: $value');
        });
      }
    } else if (input == '2') {
      stdout.write('Enter preference key: ');
      final key = stdin.readLineSync();
      if (key == null || key.isEmpty) {
        print('Invalid key.');
        continue;
      }
      stdout.write('Enter preference value: ');
      final value = stdin.readLineSync();
      if (value == null) {
        print('Invalid value.');
        continue;
      }
      prefs[key] = value;
      await file.writeAsString(jsonEncode(prefs));
      print('Preference saved.');
    } else if (input == '3') {
      stdout.write('Enter preference key to delete: ');
      final key = stdin.readLineSync();
      if (key == null || key.isEmpty) {
        print('Invalid key.');
        continue;
