      if (prefs.remove(key) != null) {
        await file.writeAsString(jsonEncode(prefs));
        print('Preference deleted.');
      } else {
        print('Preference not found.');
      }
    } else if (input == '4') {
      print('Goodbye!');
      break;
    } else {
      print('Invalid option. Please choose 1-4.');
    }
  }
}

import 'dart:async';
import 'dart:convert';
import 'dart:io';

///
/// Real-Time Collaborative Whiteboard Server (WebSocket)
///
/// Usage:
///   dart run this_script.dart
///
/// Open browser clients to ws://localhost:8080
/// Each client can send JSON messages:
///   { "type": "draw", "from": [x1, y1], "to": [x2, y2], "color": "#ff0000", "width": 2 }
///
/// All draw events are broadcast to all connected clients in real-time.
///

@pragma('vm:entry-point')
void main() async {
  final whiteboardState = <Map<String, dynamic>>[]; // List of drawing actions
  final clients = <WebSocket>{};

  final server = await HttpServer.bind(InternetAddress.anyIPv4, 8080);
  print('WebSocket whiteboard server running on ws://localhost:8080');

  await for (HttpRequest req in server) {
    // Upgrade only WebSocket requests
    if (WebSocketTransformer.isUpgradeRequest(req)) {
      final socket = await WebSocketTransformer.upgrade(req);
      clients.add(socket);
      print('Client connected (${clients.length} total)');

      // Send current whiteboard state to new client
      socket.add(jsonEncode({
        "type": "init",
        "actions": whiteboardState,
      }));

      // Handle incoming messages
      socket.listen((dynamic message) {
        try {
          final data = jsonDecode(message);
          if (data is Map<String, dynamic> && data['type'] == 'draw') {
            // Validate and store the draw action
            if (data.containsKey('from') &&
                data.containsKey('to') &&
                data.containsKey('color') &&
                data.containsKey('width')) {
              whiteboardState.add(Map<String, dynamic>.from(data));
              // Broadcast to all other clients
              for (final c in clients) {
                if (c != socket) c.add(jsonEncode(data));
              }
            }
          }
        } catch (e) {
          // Ignore malformed messages
        }
      }, onDone: () {
        clients.remove(socket);
        print('Client disconnected (${clients.length} left)');
      }, onError: (e) {
        clients.remove(socket);
      });
    } else {
      // Serve a simple HTML client if browser requests /
      if (req.uri.path == "/") {
        req.response.headers.contentType = ContentType.html;
        req.response.write(_htmlClient);
        await req.response.close();
      } else {
        req.response.statusCode = HttpStatus.notFound;
        await req.response.close();
      }
    }
  }
}

// Simple HTML/JS client served for convenience
const _htmlClient = '''
<!DOCTYPE html>
<html>
<head>
  <title>Realtime Whiteboard</title>
  <style>
    body { margin: 0; }
    #board { border: 1px solid #ccc; touch-action: none; }
    #toolbar { padding: 8px; background: #eee; }
  </style>
</head>
<body>
  <div id="toolbar">
    Color: <input type="color" id="color" value="#000000">
    Width: <input type="range" id="width" min="1" max="10" value="2">
    <span id="status"></span>
  </div>
  <canvas id="board" width="800" height="600"></canvas>
  <script>
    const canvas = document.getElementById('board');
    const ctx = canvas.getContext('2d');
    let drawing = false, prev = null;
    const colorInput = document.getElementById('color');
    const widthInput = document.getElementById('width');
    const status = document.getElementById('status');

    // Connect WebSocket
    let ws;
    function connect() {
      ws = new WebSocket('ws://' + location.host);
      ws.onopen = () => status.textContent = 'Connected';
      ws.onclose = () => { status.textContent = 'Disconnected. Reconnecting...'; setTimeout(connect, 1000); };
      ws.onmessage = (ev) => {
        const msg = JSON.parse(ev.data);
        if (msg.type === 'init' && msg.actions) {
          // Redraw all actions
          ctx.clearRect(0,0,canvas.width,canvas.height);
          msg.actions.forEach(drawAction);
        } else if (msg.type === 'draw') {
          drawAction(msg);
        }
      };
    }
    connect();

    function drawAction(action) {
      ctx.strokeStyle = action.color || '#000';
      ctx.lineWidth = action.width || 2;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(action.from[0], action.from[1]);
      ctx.lineTo(action.to[0], action.to[1]);
      ctx.stroke();
    }

    // Mouse/touch drawing
    function getPos(e) {
      if (e.touches) {
        const rect = canvas.getBoundingClientRect();
        return [
          e.touches[0].clientX - rect.left,
          e.touches[0].clientY - rect.top
        ];
      } else {
        return [e.offsetX, e.offsetY];
      }
    }

    function startDraw(e) {
      drawing = true;
      prev = getPos(e);
      e.preventDefault();
    }
    function endDraw(e) {
      drawing = false;
      prev = null;
      e.preventDefault();
    }
    function moveDraw(e) {
      if (!drawing) return;
      const pos = getPos(e);
      // Send draw event
      const action = {
        type: 'draw',
        from: prev,
        to: pos,
        color: colorInput.value,
        width: parseInt(widthInput.value)
      };
      drawAction(action);
      if (ws && ws.readyState === 1) ws.send(JSON.stringify(action));
      prev = pos;
      e.preventDefault();
    }

    canvas.addEventListener('mousedown', startDraw);
    canvas.addEventListener('mouseup', endDraw);
    canvas.addEventListener('mouseleave', endDraw);
    canvas.addEventListener('mousemove', moveDraw);

    canvas.addEventListener('touchstart', startDraw);
    canvas.addEventListener('touchend', endDraw);
    canvas.addEventListener('touchcancel', endDraw);
    canvas.addEventListener('touchmove', moveDraw);
  </script>
</body>
</html>
''';

