      if (content.isNotEmpty) {
        offlineQueue
          ..clear()
          ..addAll(List<Map<String, dynamic>>.from(
              (content.startsWith('[') ? content : '[]') == '[]'
                  ? []
                  : (content.startsWith('[')
                      ? (content.isNotEmpty
                          ? List<Map<String, dynamic>>.from(
                              (content.isNotEmpty
                                  ? (content.startsWith('[')
                                      ? (content.isNotEmpty
                                          ? List<Map<String, dynamic>>.from(
                                              (content.isNotEmpty
                                                      ? content
                                                      : '[]')
                                                  as List)
                                          : [])
                                      : [])
                                  : []))
                          : [])
                      : [])));
      }
    }
  }

  // Save queue to disk
  Future<void> saveQueue() async {
    final file = File(queueFile);
    await file.writeAsString(offlineQueue.toString());
  }

  // Simulated network status
  bool isOnline = false;

  // Simulated API call
  Future<bool> syncAction(Map<String, dynamic> action) async {
    // Simulate network delay
    await Future.delayed(Duration(milliseconds: 500));
    if (isOnline) {
      print('Synced action: $action');
      return true;
    } else {
      print('Failed to sync (offline): $action');
      return false;
    }
  }

  // Add action to queue and persist
  Future<void> enqueueAction(Map<String, dynamic> action) async {
    offlineQueue.add(action);
    await saveQueue();
    print('Action queued: $action');
  }

  // Try to sync queue
  Future<void> processQueue() async {
    print('Processing queue...');
    int i = 0;
    while (i < offlineQueue.length) {
      final action = offlineQueue[i];
      final success = await syncAction(action);
      if (success) {
        offlineQueue.removeAt(i);
        await saveQueue();
      } else {
        i++;
      }
    }
    print('Queue processed. Remaining: ${offlineQueue.length}');
  }

  // Simulate user actions
  Future<void> simulateUserActions() async {
    await enqueueAction({'type': 'create', 'item': 'Task 1'});
    await enqueueAction({'type': 'update', 'item': 'Task 2'});
    await enqueueAction({'type': 'delete', 'item': 'Task 3'});
  }

  // Simulate going online
  Future<void> goOnline() async {
    isOnline = true;
    print('\n--- Device is ONLINE ---\n');
    await processQueue();
  }

  // Simulate going offline
  Future<void> goOffline() async {
    isOnline = false;
    print('\n--- Device is OFFLINE ---\n');
  }

  // ---- Main logic ----
  print('Offline Queue Sync Demo\n');

  // Load any existing queue
  await loadQueue();

  // Start offline
