import 'dart:convert';

class Session {
  final String username;
  final String sessionId;
  DateTime lastActive;

  Session(this.username, this.sessionId) : lastActive = DateTime.now();

  bool get isActive => DateTime.now().difference(lastActive).inMinutes < 10;

  void refresh() {
    lastActive = DateTime.now();
  }
}

@pragma('vm:entry-point')
void main() async {
  // In-memory user database (username: password)
  final users = <String, String>{
    'alice': 'password123',
    'bob': 'qwerty',
  };

  // In-memory session store (sessionId: Session)
  final sessions = <String, Session>{};

  String? currentSessionId;

  String prompt(String message) {
    stdout.write(message);
    return stdin.readLineSync(encoding: utf8)?.trim() ?? '';
  }

  String generateSessionId() {
    return DateTime.now().millisecondsSinceEpoch.toString() +
        '-' +
        (1000 + (10000 * (new DateTime.now().microsecond % 1e-5)).toInt()).toString();
  }

  void login() {
    final username = prompt('Username: ');
    final password = prompt('Password: ');
    if (users[username] == password) {
      // Create new session
      final sessionId = generateSessionId();
      sessions[sessionId] = Session(username, sessionId);
      currentSessionId = sessionId;
      print('Login successful. Session started for $username.');
    } else {
      print('Invalid username or password.');
    }
  }

  void logout() {
    if (currentSessionId != null && sessions.containsKey(currentSessionId)) {
      sessions.remove(currentSessionId);
      print('Logged out successfully.');
      currentSessionId = null;
    } else {
      print('No active session to logout.');
    }
  }

  void showStatus() {
    if (currentSessionId != null && sessions.containsKey(currentSessionId)) {
      final session = sessions[currentSessionId]!;
      if (session.isActive) {
        print('User "${session.username}" is logged in. Last active: ${session.lastActive}');
      } else {
        print('Session expired for user "${session.username}". Logging out...');
        logout();
      }
    } else {
      print('No active session.');
    }
  }

  void refreshSession() {
    if (currentSessionId != null && sessions.containsKey(currentSessionId)) {
      final session = sessions[currentSessionId]!;
      session.refresh();
      print('Session refreshed for ${session.username}.');
    } else {
      print('No active session to refresh.');
    }
  }

  print('=== Dart User Session Management ===');
  print('Available users: ${users.keys.join(", ")}');
  print('Commands: login, logout, status, refresh, exit');

  while (true) {
    stdout.write('\n> ');
    final input = stdin.readLineSync(encoding: utf8)?.trim().toLowerCase();
    switch (input) {
      case 'login':
        login();
        break;
      case 'logout':
        logout();
        break;
      case 'status':
        showStatus();
        break;
      case 'refresh':
        refreshSession();
        break;
      case 'exit':
        print('Exiting...');
        return;
      default:
        print('Unknown command. Available: login, logout, status, refresh, exit');
    }
  }
}

