  print('Type "help" for a list of commands. Type "exit" to quit.');
  final history = <String>[];
  final commands = <String, String Function(List<String>)>{
    'help': (args) => '''
Available commands:
  help           Show this help message
  echo [text]    Print text to console
  time           Show current time
  history        Show entered commands
  clear          Clear the console
  exit           Quit the debug console
''',
    'echo': (args) => args.isEmpty ? 'Usage: echo [text]' : args.join(' '),
    'time': (args) => 'Current time: ${DateTime.now()}',
    'history': (args) => history.isEmpty
        ? 'No commands entered yet.'
        : history.asMap().entries.map((e) => '${e.key + 1}: ${e.value}').join('\n'),
    'clear': (args) {
      if (Platform.isWindows) {
        // Windows clear
        stdout.write('\x1B[2J\x1B[0;0H');
      } else {
        // ANSI escape code for clear
        stdout.write('\x1B[2J\x1B[H');
      }
      return '';
    },
    'exit': (args) => 'exit',
  };

  while (true) {
    stdout.write('> ');
    final input = stdin.readLineSync();
    if (input == null) {
      print('\nExiting debug console.');
      break;
    }
    final trimmed = input.trim();
    if (trimmed.isEmpty) continue;
    history.add(trimmed);

    final parts = trimmed.split(' ');
    final cmd = parts.first;
    final args = parts.skip(1).toList();

    if (commands.containsKey(cmd)) {
      final result = commands[cmd]!(args);
      if (cmd == 'exit' || result == 'exit') {
        print('Exiting debug console.');
        break;
      }
      if (cmd != 'clear' && result.isNotEmpty) print(result);
    } else {
      print('Unknown command: "$cmd". Type "help" for a list of commands.');
    }
  }
}

