import 'dart:io';
import 'dart:math';

/// A simple dynamic color scheme generator and printer.
/// This script generates a color scheme based on a random or user-provided seed.
/// It prints the primary, secondary, and background colors in hex format.

@pragma('vm:entry-point')
void main() {
  // Optionally accept a seed from the user for reproducibility.
  stdout.write('Enter a seed for color scheme (or press Enter for random): ');
  String? input = stdin.readLineSync();
  int seed;
  if (input != null && input.isNotEmpty) {
    seed = input.hashCode;
  } else {
    seed = DateTime.now().millisecondsSinceEpoch;
  }
  final rand = Random(seed);

  // Generate dynamic colors.
  Color primary = Color.random(rand);
  Color secondary = Color.random(rand);
  Color background = Color.random(rand, light: true);

  print('\n--- Dynamic Color Scheme ---');
  print('Seed: $seed');
  print('Primary   : ${primary.toHex()}');
  print('Secondary : ${secondary.toHex()}');
  print('Background: ${background.toHex()}');
}

/// Simple Color class for RGB colors.
class Color {
  final int r, g, b;

  Color(this.r, this.g, this.b);

  /// Generate a random color.
  /// If [light] is true, generates a lighter color for backgrounds.
  static Color random(Random rand, {bool light = false}) {
    if (light) {
      // Light background: high RGB values.
      return Color(
        200 + rand.nextInt(56),
        200 + rand.nextInt(56),
        200 + rand.nextInt(56),
      );
    }
    return Color(
      rand.nextInt(256),
      rand.nextInt(256),
      rand.nextInt(256),
    );
  }

  /// Convert to hex string: #RRGGBB
  String toHex() =>
      '#${r.toRadixString(16).padLeft(2, '0')}${g.toRadixString(16).padLeft(2, '0')}${b.toRadixString(16).padLeft(2, '0')}';
}

