/// A simple in-app event tracking implementation.
/// Events are logged to the console in JSON format.

class AnalyticsEvent {
  final String name;
  final Map<String, dynamic> parameters;
  final DateTime timestamp;

  AnalyticsEvent(this.name, this.parameters)
      : timestamp = DateTime.now();

  Map<String, dynamic> toJson() => {
        'name': name,
        'parameters': parameters,
        'timestamp': timestamp.toIso8601String(),
      };
}

class EventTracker {
  final List<AnalyticsEvent> _events = [];

  void track(String eventName, [Map<String, dynamic> parameters = const {}]) {
    final event = AnalyticsEvent(eventName, parameters);
    _events.add(event);
    print('Tracked event: ${jsonEncode(event.toJson())}');
  }

  void printSummary() {
    print('\nEvent Tracking Summary:');
    final countByName = <String, int>{};
    for (final event in _events) {
      countByName[event.name] = (countByName[event.name] ?? 0) + 1;
    }
    countByName.forEach((name, count) {
      print('  $name: $count');
    });
  }
}

