import 'dart:convert';
import 'dart:io';
import 'dart:math';

/// Simulates an offline analytics logger.
/// Events are stored locally in a file when offline,
/// and sent (printed) when online.
@pragma('vm:entry-point')
void main() async {
  final analyticsFile = File('offline_analytics.json');
  final random = Random();

  // Simulate online/offline status randomly
  bool isOnline() => random.nextBool();

  // Simulate logging an event
  Future<void> logEvent(String eventName, Map<String, dynamic> parameters) async {
    final event = {
      'event': eventName,
      'parameters': parameters,
      'timestamp': DateTime.now().toIso8601String(),
    };

    if (isOnline()) {
      // Send event immediately (simulate by printing)
      print('Sent online: ${jsonEncode(event)}');
    } else {
      // Save event locally for later sending
      List<Map<String, dynamic>> events = [];
      if (await analyticsFile.exists()) {
        final content = await analyticsFile.readAsString();
        if (content.isNotEmpty) {
          events = List<Map<String, dynamic>>.from(jsonDecode(content));
        }
      }
      events.add(event);
      await analyticsFile.writeAsString(jsonEncode(events));
      print('Saved offline: ${jsonEncode(event)}');
    }
  }

  // Try to send any stored offline events if online
  Future<void> flushOfflineEvents() async {
    if (!await analyticsFile.exists()) return;
    final content = await analyticsFile.readAsString();
    if (content.isEmpty) return;

    List<Map<String, dynamic>> events = List<Map<String, dynamic>>.from(jsonDecode(content));
    if (events.isEmpty) return;

    if (isOnline()) {
      for (final event in events) {
        // Simulate sending event (printing)
        print('Flushed online: ${jsonEncode(event)}');
      }
      await analyticsFile.writeAsString(''); // Clear stored events
    } else {
      print('Still offline, cannot flush events.');
    }
  }

  // Simulate app usage
  print('Simulating analytics logging...');
  await logEvent('app_open', {'source': 'icon'});
  await logEvent('button_click', {'button': 'login'});
  await logEvent('purchase', {'item_id': 123, 'amount': 4.99});

  print('\nAttempting to flush offline events...');
  await flushOfflineEvents();

  print('\nDone.');
}

