void main() {
  // Define the graph as an adjacency list (undirected graph for simplicity)
  Map<int, List<int>> graph = {
    0: [1, 2],
    1: [0, 3],
    2: [0, 3],
    3: [1, 2, 4],
    4: [3, 5],
    5: [4],
  };

  // Set of visited nodes
  Set<int> visited = HashSet<int>();

  // List to store the DFS traversal order
  List<int> traversal = [];

  // Recursive DFS function
  void dfs(int node) {
    visited.add(node);
    traversal.add(node);

    for (int neighbor in graph[node] ?? []) {
      if (!visited.contains(neighbor)) {
        dfs(neighbor);
      }
    }
  }

  // Start DFS from node 0
  dfs(0);

  // Print the traversal order
  print('DFS Traversal Order: ${traversal.join(' -> ')}');
}

