void main() {
  // Define the graph as an adjacency list: Map from node to list of [neighbor, weight]
  Map<int, List<List<int>>> graph = {
    0: [[1, 4], [2, 2]],
    1: [[3, 1], [4, 7]],
    2: [[1, 3], [3, 9]],
    3: [[4, 5]],
    4: [],
  };

  int n = graph.length; // Number of nodes (assuming nodes are 0 to n-1)
  int source = 0; // Starting node

  // Initialize distances to infinity (use a large number for int)
  const int INF = 999999;
  List<int> dist = List.filled(n, INF);
  dist[source] = 0;

  // Visited array
  List<bool> visited = List.filled(n, false);

  // Dijkstra's algorithm
  for (int count = 0; count < n; count++) {
    // Find the unvisited node with the smallest distance
    int minDist = INF;
    int u = -1;
    for (int i = 0; i < n; i++) {
      if (!visited[i] && dist[i] < minDist) {
        minDist = dist[i];
        u = i;
      }
    }

    // If no node found, break (graph might be disconnected)
    if (u == -1) break;

    // Mark as visited
    visited[u] = true;

    // Update distances for neighbors
    if (graph.containsKey(u)) {
      for (var neighbor in graph[u]!) {
        int v = neighbor[0];
        int weight = neighbor[1];
        if (!visited[v] && dist[u] + weight < dist[v]) {
          dist[v] = dist[u] + weight;
        }
      }
    }
  }

  // Print the shortest distances from source
  print('Shortest distances from node $source:');
  for (int i = 0; i < n; i++) {
    String distance = (dist[i] == INF) ? 'Infinity' : dist[i].toString();
    print('To node $i: $distance');
  }
}

