class GrowableList<E> {
  List<E?> _data;
  int _length;
  int _capacity;

  /// Creates a new growable list with the specified initial capacity.
  /// [initialCapacity] must be non-negative. Defaults to 10 if not provided.
  GrowableList([int initialCapacity = 10]) {
    if (initialCapacity < 0) {
      throw ArgumentError('Initial capacity must be non-negative');
    }
    _capacity = initialCapacity;
    _data = List<E?>.filled(_capacity, null);
    _length = 0;
  }

  /// Adds an element to the end of the list, growing the capacity if necessary.
  void add(E element) {
    if (_length == _capacity) {
      _growToNextCapacity();
    }
    _data[_length] = element;
    _length++;
  }

  /// Grows the list's capacity to the next size (doubling it) and copies existing elements.
  void _growToNextCapacity() {
    _capacity = _capacity * 2;
    var newData = List<E?>.filled(_capacity, null);
    for (int i = 0; i < _length; i++) {
      newData[i] = _data[i];
    }
    _data = newData;
  }

  /// Returns the current number of elements in the list.
  int get length => _length;

  /// Accesses the element at the specified index.
  E? operator [](int index) {
    if (index < 0 || index >= _length) {
