  // Find the maximum number to determine the number of digits needed for radix sort
  int max = arr[0];
  for (int i = 1; i < arr.length; i++) {
    if (arr[i] > max) {
      max = arr[i];
    }
  }

  // Perform radix sort: iterate through each digit place (units, tens, hundreds, etc.)
  for (int exp = 1; max ~/ exp > 0; exp *= 10) {
    // Initialize output array for sorted values and count array for digit frequencies
    List<int> output = List<int>.filled(arr.length, 0);
    List<int> count = List<int>.filled(10, 0); // 10 possible digits (0-9)

    // Count occurrences of each digit at the current place (exp)
    for (int i = 0; i < arr.length; i++) {
      int digit = (arr[i] ~/ exp) % 10;
      count[digit]++;
    }

    // Transform count array into cumulative counts to determine positions in output
    for (int i = 1; i < 10; i++) {
      count[i] += count[i - 1];
    }

    // Build the output array by placing elements in sorted order (stable sort)
    for (int i = arr.length - 1; i >= 0; i--) {
      int digit = (arr[i] ~/ exp) % 10;
      output[count[digit] - 1] = arr[i];
      count[digit]--;
    }

    // Copy the sorted output back to the original array
    for (int i = 0; i < arr.length; i++) {
      arr[i] = output[i];
    }
