  for (int i = 0; i < V; i++) {
    if (dist[i][i] < 0) {
      hasNegativeCycle = true;
      break;
    }
  }

  if (hasNegativeCycle) {
    print('Graph contains a negative cycle');
  } else {
    // Print the shortest distance matrix
