import 'dart:io';

// Helper function to check if a number can be placed safely in the grid
bool isSafe(List<List<int>> grid, int row, int col, int num) {
  // Check the row
  for (int x = 0; x < 9; x++) {
    if (grid[row][x] == num) {
      return false;
    }
  }

  // Check the column
  for (int x = 0; x < 9; x++) {
    if (grid[x][col] == num) {
      return false;
    }
  }

  // Check the 3x3 box
  int startRow = row - row % 3;
  int startCol = col - col % 3;
  for (int i = 0; i < 3; i++) {
    for (int j = 0; j < 3; j++) {
      if (grid[i + startRow][j + startCol] == num) {
        return false;
      }
    }
  }

  return true;
}

// Helper function to solve the Sudoku using backtracking
bool solveSudoku(List<List<int>> grid) {
  int row = -1;
  int col = -1;
  bool isEmpty = true;

  // Find an empty cell (0 represents empty)
  for (int i = 0; i < 9; i++) {
    for (int j = 0; j < 9; j++) {
      if (grid[i][j] == 0) {
        row = i;
        col = j;
        isEmpty = false;
        break;
      }
    }
    if (!isEmpty) {
      break;
    }
  }

  // If no empty cell, puzzle is solved
  if (isEmpty) {
    return true;
  }

  // Try numbers 1 to 9
  for (int num = 1; num <= 9; num++) {
    if (isSafe(grid, row, col, num)) {
      grid[row][col] = num;

      // Recurse to solve the rest
      if (solveSudoku(grid)) {
        return true;
      }

      // Backtrack
      grid[row][col] = 0;
    }
  }

  return false; // No solution found
}

// Helper function to print the grid
void printGrid(List<List<int>> grid) {
  for (int i = 0; i < 9; i++) {
    for (int j = 0; j < 9; j++) {
      stdout.write('${grid[i][j]} ');
    }
    stdout.writeln();
  }
}

