  List<List<int>> graph = [
    [0, 1, 0, 1, 0], // 0 connected to 1 and 3
    [1, 0, 1, 1, 1], // 1 connected to 0,2,3,4
    [0, 1, 0, 0, 1], // 2 connected to 1 and 4
    [1, 1, 0, 0, 1], // 3 connected to 0,1,4
    [0, 1, 1, 1, 0], // 4 connected to 1,2,3
