  // Path array to store the current path
  List<int> path = List<int>.filled(numVertices, -1);

  // Function to check if it's safe to add vertex v to the path at position pos
  bool isSafe(int v, int pos) {
    // Check if v is adjacent to the previous vertex in the path
    if (graph[path[pos - 1]][v] == 0) {
      return false;
    }

    // Check if v is already in the path
    for (int i = 0; i < pos; i++) {
      if (path[i] == v) {
        return false;
      }
    }

    return true;
  }

  // Recursive function to find Hamiltonian path
  bool hamPathUtil(int pos) {
    // Base case: If all vertices are in the path
    if (pos == numVertices) {
      return true;
    }

    // Try different vertices as next candidate in the path
    for (int v = 1; v < numVertices; v++) { // Start from 1 since 0 is the starting point
      if (isSafe(v, pos)) {
        path[pos] = v;

        // Recur to construct rest of the path
        if (hamPathUtil(pos + 1)) {
          return true;
        }

        // Backtrack
        path[pos] = -1;
      }
    }

    return false;
  }

  // Start from vertex 0
  path[0] = 0;

  // Call the utility function
