void main() {
  // Sample text and pattern
  String text = "ABABDABACDABABCABAB";
  String pattern = "ABABCABAB";

  // Compute the LPS (Longest Prefix Suffix) array for the pattern
  List<int> lps = List<int>.filled(pattern.length, 0);
  int length = 0; // Length of the previous longest prefix suffix
  lps[0] = 0; // LPS[0] is always 0
  int i = 1;

  while (i < pattern.length) {
    if (pattern[i] == pattern[length]) {
      length++;
      lps[i] = length;
      i++;
    } else {
      if (length != 0) {
        length = lps[length - 1];
      } else {
        lps[i] = 0;
        i++;
      }
    }
  }

  // Now perform KMP search
  List<int> matches = [];
  int textIndex = 0; // Index for text
  int patIndex = 0; // Index for pattern

  while (textIndex < text.length) {
    if (pattern[patIndex] == text[textIndex]) {
      patIndex++;
      textIndex++;
    }

    if (patIndex == pattern.length) {
      // Pattern found at index (textIndex - patIndex)
      matches.add(textIndex - patIndex);
      patIndex = lps[patIndex - 1];
    } else if (textIndex < text.length && pattern[patIndex] != text[textIndex]) {
      if (patIndex != 0) {
        patIndex = lps[patIndex - 1];
      } else {
        textIndex++;
      }
    }
  }

  // Output the results
  print("Text: $text");
  print("Pattern: $pattern");
  if (matches.isEmpty) {
    print("No matches found.");
  } else {
    print("Pattern found at positions: ${matches.join(', ')}");
  }
}

