// The logic is implemented within the main function using local helper functions.

@pragma('vm:entry-point')
void main() {
  // Example text and pattern
  String text = "HERE IS A SIMPLE EXAMPLE";
  String pattern = "EXAMPLE";

  // Local function to compute the bad character heuristic table
  Map<int, int> buildBadCharTable(String pat) {
    var table = <int, int>{};
    int m = pat.length;
    for (int i = 0; i < m - 1; i++) {
      table[pat.codeUnitAt(i)] = m - 1 - i;
    }
    return table;
  }

  // Local function to check if a suffix is a prefix
  bool isPrefix(String pat, int p) {
    int m = pat.length;
    int j = 0;
    for (int i = p; i < m; i++) {
      if (pat[i] != pat[j]) return false;
      j++;
    }
    return true;
  }

  // Local function to compute the length of the longest suffix
  int suffixLength(String pat, int p) {
    int m = pat.length;
    int len = 0;
    int i = p;
    int j = m - 1;
    while (i >= 0 && pat[i] == pat[j]) {
      len++;
      i--;
      j--;
    }
    return len;
  }

  // Local function to compute the good suffix heuristic table
  List<int> buildGoodSuffixTable(String pat) {
    int m = pat.length;
    var table = List<int>.filled(m, 0);
    int lastPrefixPosition = m;
    for (int i = m; i > 0; i--) {
      if (isPrefix(pat, i)) lastPrefixPosition = i;
      table[m - i] = lastPrefixPosition - i + m;
    }
    for (int i = 0; i < m - 1; i++) {
      int slen = suffixLength(pat, i);
      table[slen] = m - 1 - i + slen;
    }
    return table;
  }

  // Local function for Boyer-Moore search
  List<int> boyerMooreSearch(String txt, String pat) {
    List<int> positions = [];
    if (pat.isEmpty) return positions;

    int n = txt.length;
    int m = pat.length;
    if (m > n) return positions;

    var badCharTable = buildBadCharTable(pat);
    var goodSuffixTable = buildGoodSuffixTable(pat);

    int i = 0;
    while (i <= n - m) {
      int j = m - 1;
      while (j >= 0 && pat[j] == txt[i + j]) {
        j--;
      }
      if (j < 0) {
        // Match found
        positions.add(i);
        i += goodSuffixTable[0];
      } else {
        // Use bad character rule
        int charShift = badCharTable[txt.codeUnitAt(i + j)] ?? m;
        // Use good suffix rule
        int suffixShift = goodSuffixTable[j + 1];
        i += (charShift > suffixShift) ? charShift : suffixShift;
      }
    }
    return positions;
  }

  // Perform the search
  List<int> result = boyerMooreSearch(text, pattern);

  // Output the result
  if (result.isNotEmpty) {
    print("Pattern found at positions: $result");
  } else {
    print("Pattern not found.");
  }
}

