    print('No modular inverse exists for $a mod $originalM (gcd is $m)');
  } else {
    // Adjust lastY to be positive modulo originalM
    int inverse = (lastY % originalM + originalM) % originalM;
    print('Modular inverse of $a mod $originalM is $inverse');
