import 'dart:math';

void main() {
  // Initialize the array
  List<int> arr = [2, 3, 1, 4, 5, 0, 6];
  int n = arr.length;

  // Compute log2(n) for sparse table dimensions
  int logn = (log(n) / log(2)).floor() + 1;

  // Initialize the sparse table with zeros
  List<List<int>> st = List.generate(n, (_) => List.filled(logn, 0));

  // Fill base cases: each element is the min of its own segment (length 1)
  for (int i = 0; i < n; i++) {
    st[i][0] = arr[i];
  }

  // Build the sparse table: for each jump size j, compute min for segments of length 2^j
  for (int j = 1; j < logn; j++) {
    for (int i = 0; i + (1 << j) <= n; i++) {
      st[i][j] = min(st[i][j - 1], st[i + (1 << (j - 1))][j - 1]);
    }
  }

  // Define the query function for RMQ
  int query(int L, int R) {
    int len = R - L + 1;
    int k = (log(len) / log(2)).floor(); // Find the largest k such that 2^k <= len
    return min(st[L][k], st[R - (1 << k) + 1][k]);
  }

  // Perform example queries and print results
  print('Min from 0 to 5: ${query(0, 5)}'); // Expected: 0
  print('Min from 1 to 3: ${query(1, 3)}'); // Expected: 1
  print('Min from 2 to 6: ${query(2, 6)}'); // Expected: 0
  print('Min from 4 to 4: ${query(4, 4)}'); // Expected: 5
}
