import 'dart:collection';

@pragma('vm:entry-point')
void main() {
  // Sample graph: nodes 0 to 3 with edges forming SCCs {0}, {1,2,3}
  int n = 4;
  Map<int, List<int>> graph = {
    0: [1],
    1: [2],
    2: [3],
    3: [1],
  };

  // Initialize discovery and low arrays
  List<int> disc = List.filled(n, -1);
  List<int> low = List.filled(n, -1);

  // Stack and onStack tracker
  List<int> stack = [];
  Set<int> onStack = HashSet<int>();

  // Time index
  int time = 0;

  // List to hold SCCs
  List<List<int>> sccs = [];

  // DFS function for Tarjan's algorithm
  void dfs(int u) {
    disc[u] = low[u] = time++;
    stack.add(u);
    onStack.add(u);

    for (int v in graph[u] ?? []) {
      if (disc[v] == -1) {
        dfs(v);
        low[u] = low[u] < low[v] ? low[u] : low[v];
      } else if (onStack.contains(v)) {
        low[u] = low[u] < disc[v] ? low[u] : disc[v];
      }
    }

    if (low[u] == disc[u]) {
      List<int> scc = [];
      while (true) {
        int v = stack.removeLast();
        onStack.remove(v);
        scc.add(v);
        if (v == u) break;
      }
      sccs.add(scc);
    }
  }

  // Call DFS for each unvisited node
  for (int i = 0; i < n; i++) {
    if (disc[i] == -1) {
      dfs(i);
    }
  }

  // Print the SCCs
  print('Strongly Connected Components:');
  for (var scc in sccs) {
    print(scc);
  }
}

