import 'dart:io';

@pragma('vm:entry-point')
void main() {
  // Helper function to get transpose graph
  List<List<int>> getTranspose(int V, List<List<int>> graph) {
    List<List<int>> trans = List.generate(V, (_) => []);
    for (int u = 0; u < V; u++) {
      for (int v in graph[u]) {
        trans[v].add(u);
      }
    }
    return trans;
  }

  // DFS for first pass to fill the stack with finishing times
  void dfsFirst(int u, List<bool> visited, List<List<int>> graph, List<int> stack) {
    visited[u] = true;
    for (int v in graph[u]) {
      if (!visited[v]) {
        dfsFirst(v, visited, graph, stack);
      }
    }
    stack.add(u);
  }

  // DFS for second pass to find SCC components
  void dfsSecond(int u, List<bool> visited, List<List<int>> graph, List<int> component) {
    visited[u] = true;
    component.add(u);
    for (int v in graph[u]) {
      if (!visited[v]) {
        dfsSecond(v, visited, graph, component);
      }
    }
  }

  // Sample graph with 5 vertices
  int V = 5;
  List<List<int>> graph = List.generate(V, (_) => []);

  // Adding edges
  graph[0].add(1);
  graph[1].add(2);
  graph[2].add(3);
  graph[3].add(0);
  graph[1].add(4);

  // Step 1: Perform DFS on original graph and fill stack
  List<int> stack = [];
  List<bool> visited = List<bool>.filled(V, false);
  for (int i = 0; i < V; i++) {
    if (!visited[i]) {
      dfsFirst(i, visited, graph, stack);
    }
