  final Point b;
  final Point c;

  Triangle(this.a, this.b, this.c);

  @override
  String toString() => 'Triangle[$a, $b, $c]';

  bool containsPoint(Point p) {
    return p == a || p == b || p == c;
  }
}

// Function to compute the circumcircle of a triangle and check if a point is inside it
bool inCircumcircle(Point a, Point b, Point c, Point p) {
  final ax = a.x - p.x;
  final ay = a.y - p.y;
  final bx = b.x - p.x;
  final by = b.y - p.y;
  final cx = c.x - p.x;
  final cy = c.y - p.y;

  final det = (ax * (by * cy * (by - cy) - cy * by * (by - cy)) -
          ay * (bx * cy * (bx - cx) - cx * by * (bx - cx)) +
          ax * (bx * cy * (bx - cx) - cx * by * (bx - cx))) /
      2;

  final absDet = det.abs();
  final radius = (ax * ax + ay * ay) *
      (bx * bx + by * by) *
      (cx * cx + cy * cy) /
      (2 * absDet);

  final dist = (p.x - a.x) * (p.x - a.x) + (p.y - a.y) * (p.y - a.y);

  // Simplified check: actual in-circle test using determinant
