      ay * (bx * (cx * cx + cy * cy) - cx * (bx * bx + by * by)) +
      (ax * (bx * (cx * cx + cy * cy) - cx * (bx * bx + by * by)));

  return d > 0; // Note: This is a simplified version; adjust for edge cases if needed
}

// Function to check if two triangles share an edge
bool sharesEdge(Triangle t1, Triangle t2) {
  final points1 = {t1.a, t1.b, t1.c};
  final points2 = {t2.a, t2.b, t2.c};
  return points1.intersection(points2).length == 2;
}

// Main Delaunay triangulation function
List<Triangle> delaunayTriangulation(List<Point> points) {
  if (points.length < 3) return [];

  // Find min and max to create super triangle
  double minX = points.map((p) => p.x).reduce(math.min);
