    int h1 = hash1(key);
    if (table1[h1] == null) {
      table1[h1] = key;
      return true;
    }

    int h2 = hash2(key);
    if (table2[h2] == null) {
      table2[h2] = key;
      return true;
    }

    // Cuckoo eviction process
    int currentKey = key;
    bool useTable1 = true; // Start evicting from table1
    for (int i = 0; i < size * 2; i++) { // Prevent infinite loop
      if (useTable1) {
        int index = hash1(currentKey);
        int? evicted = table1[index];
        table1[index] = currentKey;
        if (evicted == null) return true;
        currentKey = evicted;
        useTable1 = false;
      } else {
        int index = hash2(currentKey);
        int? evicted = table2[index];
        table2[index] = currentKey;
        if (evicted == null) return true;
        currentKey = evicted;
        useTable1 = true;
      }
    }
    // If loop limit reached, insertion failed (rehash needed in real impl)
    return false;
  }

  bool lookup(int key) {
    return table1[hash1(key)] == key || table2[hash2(key)] == key;
  }

  void printTables() {
    print('Table 1: $table1');
    print('Table 2: $table2');
  }
}

