@pragma('vm:entry-point')
void main() {
  // Objective function to minimize: f(x, y) = (x-1)^2 + (y-1)^2 + sin(3*x) + sin(3*y) for some local minima
  double objective(List<double> solution) {
    double x = solution[0];
    double y = solution[1];
    return (x - 1) * (x - 1) + (y - 1) * (y - 1) + sin(3 * x) + sin(3 * y);
  }

  // Generate a random initial solution in [-5, 5] for x and y
  Random rand = Random();
  List<double> current = [rand.nextDouble() * 10 - 5, rand.nextDouble() * 10 - 5];
  double currentCost = objective(current);

  // Best solution tracking
  List<double> best = List.from(current);
  double bestCost = currentCost;

  // Parameters
  double initialTemp = 100.0;
  double finalTemp = 0.1;
  int maxIterations = 10000;
  double coolingRate = 0.995; // Geometric cooling

  double temp = initialTemp;

  for (int i = 0; i < maxIterations; i++) {
    // Generate a neighbor: perturb by small random amount
    List<double> candidate = List.from(current);
    candidate[0] += rand.nextDouble() * 0.1 - 0.05;
    candidate[1] += rand.nextDouble() * 0.1 - 0.05;

    double candidateCost = objective(candidate);

    // Calculate cost difference
    double costDiff = candidateCost - currentCost;

    // Decide whether to accept the candidate
    if (costDiff < 0 || rand.nextDouble() < exp(-costDiff / temp)) {
      current = candidate;
      currentCost = candidateCost;

      // Update best if better
      if (currentCost < bestCost) {
        best = List.from(current);
        bestCost = currentCost;
      }
    }

    // Cool down the temperature (geometric cooling)
    temp *= coolingRate;

    // Stop if temperature is too low
    if (temp < finalTemp) {
      break;
    }
  }

  // Output the result
  print('Best solution: x=${best[0]}, y=${best[1]}');
  print('Best cost: $bestCost');
}

