import 'dart:math';

class Individual {
  List<int> chromosome;
  double fitness;

  Individual(this.chromosome) : fitness = 0.0;

  void calculateFitness() {
    fitness = chromosome.reduce((a, b) => a + b).toDouble();
  }
}

List<Individual> createInitialPopulation(int populationSize, int chromosomeLength) {
  final random = Random();
  return List.generate(populationSize, (_) {
    final chromosome = List.generate(chromosomeLength, (_) => random.nextInt(2));
    final individual = Individual(chromosome);
    individual.calculateFitness();
    return individual;
  });
}

Individual tournamentSelection(List<Individual> population, int tournamentSize) {
  final random = Random();
  final tournament = List<Individual>.generate(tournamentSize, (_) => population[random.nextInt(population.length)]);
  tournament.sort((a, b) => b.fitness.compareTo(a.fitness));
  return tournament.first;
}

List<Individual> crossover(Individual parent1, Individual parent2) {
  final random = Random();
  final crossoverPoint = random.nextInt(parent1.chromosome.length);
  final child1 = Individual([...parent1.chromosome.sublist(0, crossoverPoint), ...parent2.chromosome.sublist(crossoverPoint)]);
  final child2 = Individual([...parent2.chromosome.sublist(0, crossoverPoint), ...parent1.chromosome.sublist(crossoverPoint)]);
  return [child1, child2];
}

void mutate(Individual individual, double mutationRate) {
  final random = Random();
  for (int i = 0; i < individual.chromosome.length; i++) {
    if (random.nextDouble() < mutationRate) {
      individual.chromosome[i] = 1 - individual.chromosome[i];
    }
  }
}

@pragma('vm:entry-point')
void main() {
  const populationSize = 20;
  const chromosomeLength = 10;
  const generations = 50;
  const tournamentSize = 3;
  const mutationRate = 0.01;

  var population = createInitialPopulation(populationSize, chromosomeLength);

  for (int generation = 0; generation < generations; generation++) {
    final newPopulation = <Individual>[];

    while (newPopulation.length < populationSize) {
      final parent1 = tournamentSelection(population, tournamentSize);
      final parent2 = tournamentSelection(population, tournamentSize);
      final children = crossover(parent1, parent2);
      for (var child in children) {
        mutate(child, mutationRate);
        child.calculateFitness();
        newPopulation.add(child);
        if (newPopulation.length >= populationSize) break;
      }
    }

    population = newPopulation;
    population.sort((a, b) => b.fitness.compareTo(a.fitness));
    print('Generation $generation: Best fitness = ${population.first.fitness}');
  }

  print('Final best individual: ${population.first.chromosome} with fitness ${population.first.fitness}');
}

