  // Helper function for backtracking
  void backtrack(List<int> current, List<bool> used) {
    if (current.length == nums.length) {
      result.add(List.from(current));
      return;
    }

    for (int i = 0; i < nums.length; i++) {
      if (!used[i]) {
        used[i] = true;
        current.add(nums[i]);
        backtrack(current, used);
        current.removeLast();
        used[i] = false;
      }
    }
  }

  // Initialize used array
  List<bool> used = List<bool>.filled(nums.length, false);

  // Start backtracking with empty current list
  backtrack([], used);

  // Print all permutations
  for (var perm in result) {
    print(perm);
  }
}

