// A complete Dart program demonstrating alpha-beta pruning for Tic-Tac-Toe.
// The game board is represented as a list of 9 strings: ' ' for empty, 'X' for player X, 'O' for player O.
// Player X is the maximizing player, O is minimizing.
// The program finds the best move for the current player on a sample board.

import 'dart:math'; // For max and min functions.

@pragma('vm:entry-point')
void main() {
  // Helper function to create a copy of the board.
  List<String> copyBoard(List<String> board) {
    return List<String>.from(board);
  }

  // Check if a player has won.
  bool hasWon(List<String> board, String player) {
    // Rows
    if (board[0] == player && board[1] == player && board[2] == player) return true;
    if (board[3] == player && board[4] == player && board[5] == player) return true;
    if (board[6] == player && board[7] == player && board[8] == player) return true;
    // Columns
    if (board[0] == player && board[3] == player && board[6] == player) return true;
    if (board[1] == player && board[4] == player && board[7] == player) return true;
    if (board[2] == player && board[5] == player && board[8] == player) return true;
    // Diagonals
    if (board[0] == player && board[4] == player && board[8] == player) return true;
    if (board[2] == player && board[4] == player && board[6] == player) return true;
    return false;
  }

  // Check if the board is full (draw).
  bool isFull(List<String> board) {
    return !board.contains(' ');
  }

  // Get list of available moves (empty indices).
  List<int> availableMoves(List<String> board) {
    List<int> moves = [];
    for (int i = 0; i < board.length; i++) {
      if (board[i] == ' ') moves.add(i);
    }
    return moves;
  }

  // Alpha-beta pruning function.
  // Returns the score of the board.
  // Maximizing player is 'X', minimizing is 'O'.
  int alphaBeta(List<String> board, int depth, int alpha, int beta, bool isMaximizing, String maxPlayer, String minPlayer) {
    if (hasWon(board, maxPlayer)) return 10 - depth; // Max player wins.
    if (hasWon(board, minPlayer)) return depth - 10; // Min player wins.
    if (isFull(board)) return 0; // Draw.

    if (isMaximizing) {
      int maxEval = -999999; // Very low value.
      for (int move in availableMoves(board)) {
        board[move] = maxPlayer;
        int eval = alphaBeta(board, depth + 1, alpha, beta, false, maxPlayer, minPlayer);
        board[move] = ' '; // Undo move.
        maxEval = max(maxEval, eval);
        alpha = max(alpha, eval);
        if (beta <= alpha) break; // Prune.
      }
      return maxEval;
    } else {
      int minEval = 999999; // Very high value.
      for (int move in availableMoves(board)) {
        board[move] = minPlayer;
        int eval = alphaBeta(board, depth + 1, alpha, beta, true, maxPlayer, minPlayer);
        board[move] = ' '; // Undo move.
        minEval = min(minEval, eval);
        beta = min(beta, eval);
        if (beta <= alpha) break; // Prune.
      }
      return minEval;
    }
  }

  // Function to find the best move for the current player.
  // Assumes it's maxPlayer's turn if isMaximizing is true.
  int findBestMove(List<String> board, bool isMaximizing, String maxPlayer, String minPlayer) {
    int bestScore = isMaximizing ? -999999 : 999999;
    int bestMove = -1;

    for (int move in availableMoves(board)) {
      String player = isMaximizing ? maxPlayer : minPlayer;
      board[move] = player;
      int score = alphaBeta(board, 0, -999999, 999999, !isMaximizing, maxPlayer, minPlayer);
      board[move] = ' '; // Undo.

      if (isMaximizing) {
        if (score > bestScore) {
          bestScore = score;
          bestMove = move;
        }
      } else {
        if (score < bestScore) {
          bestScore = score;
          bestMove = move;
        }
      }
    }
    return bestMove;
  }

  // Sample board: X's turn, some moves already made.
  List<String> sampleBoard = [
    'X', 'O', 'X',
    ' ', 'O', ' ',
    ' ', ' ', ' '
  ];

  print('Sample Board:');
  print('${sampleBoard[0]} | ${sampleBoard[1]} | ${sampleBoard[2]}');
  print('${sampleBoard[3]} | ${sampleBoard[4]} | ${sampleBoard[5]}');
  print('${sampleBoard[6]} | ${sampleBoard[7]} | ${sampleBoard[8]}');

  // Assume it's X's turn (maximizing).
  bool isXTurn = true;
  String maxPlayer = 'X';
  String minPlayer = 'O';

  int bestMove = findBestMove(copyBoard(sampleBoard), isXTurn, maxPlayer, minPlayer);

  print('\nBest move for ${isXTurn ? 'X' : 'O'} is position: $bestMove (0-8 indexing)');
}

