import 'dart:math' as math;
import 'dart:collection';

/// Computes the cosine similarity between two users' rating maps.
double cosineSimilarity(Map<String, double> ratings1, Map<String, double> ratings2) {
  Set<String> commonItems = Set<String>.from(ratings1.keys).intersection(Set<String>.from(ratings2.keys));
  if (commonItems.isEmpty) return 0.0;

  double dotProduct = 0.0;
  double norm1 = 0.0;
  double norm2 = 0.0;

  for (String item in commonItems) {
    dotProduct += ratings1[item]! * ratings2[item]!;
    norm1 += math.pow(ratings1[item]!, 2);
    norm2 += math.pow(ratings2[item]!, 2);
  }

  norm1 = math.sqrt(norm1);
  norm2 = math.sqrt(norm2);

  if (norm1 == 0 || norm2 == 0) return 0.0;
  return dotProduct / (norm1 * norm2);
}

/// Predicts a rating for a target user and item using user-based collaborative filtering.
double predictRating(
    String targetUser,
    String targetItem,
    Map<String, Map<String, double>> allRatings,
    {int k = 3}) {
  // Find similarities with other users who rated the target item
  List<MapEntry<String, double>> similarities = [];
  for (String otherUser in allRatings.keys) {
    if (otherUser == targetUser) continue;
    if (!allRatings[otherUser]!.containsKey(targetItem)) continue;

    double sim = cosineSimilarity(allRatings[targetUser]!, allRatings[otherUser]!);
    if (sim > 0) {
      similarities.add(MapEntry(otherUser, sim));
    }
  }

  // Sort by similarity descending and take top k
  similarities.sort((a, b) => b.value.compareTo(a.value));
  similarities = similarities.take(k).toList();

  if (similarities.isEmpty) return 0.0; // No similar users, return default

  double numerator = 0.0;
  double denominator = 0.0;
  for (var entry in similarities) {
    String otherUser = entry.key;
    double sim = entry.value;
    double otherRating = allRatings[otherUser]![targetItem]!;
    numerator += sim * otherRating;
    denominator += sim;
  }

  return denominator > 0 ? numerator / denominator : 0.0;
}

