    Point(10, 10),
    Point(10, 11),
    Point(11, 10),
    Point(11, 11),
    Point(20, 20), // Noise
  ];

  double eps = 1.5;
  int minPts = 3;

  List<List<Point>> clusters = dbscan(points, eps, minPts);

  print('Found ${clusters.length} clusters:');
  for (int i = 0; i < clusters.length; i++) {
