// A complete Dart program implementing wildcard pattern matching.
// The program defines a function to check if a string matches a pattern
// with wildcards ('*' for any sequence, '?' for any single character).
// The main function tests this with examples.

bool isMatch(String s, String p) {
  // Dynamic programming table: dp[i][j] is true if s[0..i) matches p[0..j)
  final m = s.length;
  final n = p.length;
  final dp = List.generate(m + 1, (_) => List<bool>.filled(n + 1, false));

  dp[0][0] = true; // Empty string matches empty pattern

  // Handle patterns starting with '*'
  for (int j = 1; j <= n; j++) {
    if (p[j - 1] == '*') {
      dp[0][j] = dp[0][j - 1];
    }
  }

  for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= n; j++) {
      if (p[j - 1] == '*') {
        // '*' can match zero or more characters
        dp[i][j] = dp[i][j - 1] || dp[i - 1][j];
      } else if (p[j - 1] == '?' || p[j - 1] == s[i - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      }
    }
  }

  return dp[m][n];
}

@pragma('vm:entry-point')
void main() {
  // Test cases
  print(isMatch('hello', 'h*llo')); // true
  print(isMatch('hello', 'h?llo')); // true
  print(isMatch('hello', '*')); // true
  print(isMatch('hello', 'world')); // false
  print(isMatch('aa', 'a*')); // true
  print(isMatch('aa', 'a?')); // true
  print(isMatch('ab', '?*')); // true
  print(isMatch('abc', 'a?c')); // true
  print(isMatch('abc', 'a*d')); // false
}

