// Entry point function for the spawned isolate.
// This function runs in the isolate and prints periodic messages.
@pragma('vm:entry-point') // To ensure it's not optimized away
void isolateEntry(String message) {
  int tick = 0;
  Timer.periodic(Duration(seconds: 1), (timer) {
    tick++;
    print('Isolate ticking: $message $tick');
    if (tick >= 10) {
      timer.cancel(); // Prevent infinite run, but in practice, isolate is killed externally
    }
  });
}

/// Main function demonstrating isolate capabilities (pause, resume, kill).
@pragma('vm:entry-point')
Future<void> main() async {
  print('Main: Spawning isolate...');

  // Spawn a new isolate with the entry function and a message.
  Isolate isolate = await Isolate.spawn(isolateEntry, 'Hello from isolate');

  print('Main: Isolate spawned.');

  // Let the isolate run for a few seconds to observe ticking.
  await Future.delayed(Duration(seconds: 2));

  print('Main: Pausing isolate...');
  // Pause the isolate and get the resume capability.
  Capability resumeCapability = isolate.pause();

  // Wait to observe the pause effect.
  await Future.delayed(Duration(seconds: 3));

  print('Main: Resuming isolate...');
  // Resume the isolate using the capability.
  isolate.resume(resumeCapability);

  // Let it run a bit more.
  await Future.delayed(Duration(seconds: 2));

  print('Main: Killing isolate...');
  // Kill the isolate.
  isolate.kill(priority: Isolate.immediate);

  print('Main: Done.');
}

