import 'dart:async';
import 'dart:io';
import 'dart:typed_data';

@pragma('vm:entry-point')
Future<void> main() async {
  // Bind a raw server socket on localhost with a random available port.
  final server = await RawServerSocket.bind(InternetAddress.loopbackIPv4, 0);
  print('Server listening on port ${server.port}');

  // Listen for incoming connections.
  final serverSubscription = server.listen((RawSocket clientSocket) {
    print('Server: Client connected');

    // Handle reading from the client and echoing back.
    clientSocket.listen((RawSocketEvent event) {
      if (event == RawSocketEvent.read) {
        final data = clientSocket.read();
        if (data != null) {
          print('Server: Received data: ${String.fromCharCodes(data)}');
          // Echo back the data.
          clientSocket.write(data);
        }
      } else if (event == RawSocketEvent.closed) {
        print('Server: Client connection closed');
        clientSocket.close();
      }
    });
  });

  // Now, create a client to connect to the server.
  final client = await RawSocket.connect(InternetAddress.loopbackIPv4, server.port);
  print('Client: Connected to server');

  // Enable writing on the client socket.
  client.writeEventsEnabled = true;

  // Send some data from the client.
  final message = Uint8List.fromList('Hello, RawSocket!'.codeUnits);
  client.write(message);
  print('Client: Sent data');

  // Listen for response on the client.
  bool received = false;
  final clientSubscription = client.listen((RawSocketEvent event) {
    if (event == RawSocketEvent.read) {
      final data = client.read();
      if (data != null) {
        print('Client: Received echoed data: ${String.fromCharCodes(data)}');
        received = true;
        // Close the client after receiving.
        client.close();
      }
    } else if (event == RawSocketEvent.closed) {
      print('Client: Connection closed');
    }
  });

  // Wait for the client to receive the data or timeout.
  final completer = Completer<void>();
  Timer(const Duration(seconds: 5), () {
    if (!completer.isCompleted) {
      print('Timeout waiting for response');
      completer.complete();
    }
  });

  // Wait until received or timeout.
  await Future.any([completer.future, Future.delayed(Duration.zero).then((_) async {
    while (!received) {
      await Future.delayed(Duration(milliseconds: 100));
    }
    completer.complete();
  })]);

  // Cleanup.
  clientSubscription.cancel();
  await client.close();
  serverSubscription.cancel();
  await server.close();
  print('Done');
}

