        } else {
          print('Server: Received unexpected message: $message');
        }
      }, onDone: () {
        print('Server: Client disconnected');
      }, onError: (error) {
        print('Server error: $error');
      });

      // Optional: Set ping interval for WebSocket protocol-level keep-alive
      websocket.pingInterval = Duration(seconds: 5);
    } else {
      request.response
        ..statusCode = HttpStatus.forbidden
        ..close();
    }
  });

  // Connect as a client to the server
