  int i = 0;

  // Manual UTF-8 decoding loop
  while (i < bytes.length) {
    int byte1 = bytes[i];

    if (byte1 < 128) {
      // 1-byte sequence (ASCII)
      codePoints.add(byte1);
      i++;
    } else if (byte1 >= 192 && byte1 < 224) {
      // 2-byte sequence
      if (i + 1 >= bytes.length) {
        // Invalid: not enough bytes
        codePoints.add(0xFFFD); // Replacement character
        break;
      }
      int byte2 = bytes[i + 1];
      if (byte2 < 128 || byte2 >= 192) {
        // Invalid continuation byte
        codePoints.add(0xFFFD);
        i++;
        continue;
      }
      int codePoint = ((byte1 & 0x1F) << 6) | (byte2 & 0x3F);
      codePoints.add(codePoint);
      i += 2;
    } else if (byte1 >= 224 && byte1 < 240) {
      // 3-byte sequence
      if (i + 2 >= bytes.length) {
        // Invalid: not enough bytes
        codePoints.add(0xFFFD);
        break;
      }
      int byte2 = bytes[i + 1];
      int byte3 = bytes[i + 2];
      if (byte2 < 128 || byte2 >= 192 || byte3 < 128 || byte3 >= 192) {
