  const int fractionBits = 16;
  const int scale = 1 << fractionBits; // 65536

  // Helper function to convert a double to fixed-point int (uses double for input, but math will be int)
  int toFixed(double value) {
    return (value * scale).round();
  }

  // Helper function to convert fixed-point int back to double for display
  double fromFixed(int fixed) {
    return fixed / scale;
  }

  // Fixed-point addition (simple integer addition)
  int fixedAdd(int a, int b) {
    return a + b;
  }

  // Fixed-point subtraction (simple integer subtraction)
  int fixedSub(int a, int b) {
    return a - b;
  }

  // Fixed-point multiplication (multiply then divide by scale to adjust)
