// A simple in-app messaging system simulated in console.
// It maintains a message queue for different users and allows sending/receiving messages.

@pragma('vm:entry-point')
void main() {
  // Data structures for the messaging system
  // Using a Map where key is the recipient user, and value is a queue of messages
  Map<String, Queue<String>> messageQueues = {};
  // List of registered users for simulation
  List<String> users = ['Alice', 'Bob', 'Charlie'];

  // Function to register a user (initialize their queue)
  void registerUser(String user) {
    if (!messageQueues.containsKey(user)) {
      messageQueues[user] = Queue<String>();
      print('User $user registered.');
    }
  }

  // Function to send a message
  void sendMessage(String sender, String recipient, String message) {
    if (!messageQueues.containsKey(recipient)) {
      print('Recipient $recipient not found. Registering automatically.');
      registerUser(recipient);
    }
    String fullMessage = '[$sender]: $message';
    messageQueues[recipient]!.add(fullMessage);
    print('Message sent to $recipient: $fullMessage');
  }

  // Function to receive/read messages for a user
  void readMessages(String user) {
    if (!messageQueues.containsKey(user) || messageQueues[user]!.isEmpty) {
      print('No messages for $user.');
      return;
    }
    print('Messages for $user:');
    while (messageQueues[user]!.isNotEmpty) {
      print(messageQueues[user]!.removeFirst());
    }
  }

  // Register initial users
  for (var user in users) {
    registerUser(user);
  }

  // Simulate some messages
  sendMessage('Alice', 'Bob', 'Hello Bob, how are you?');
  sendMessage('Bob', 'Alice', 'Hi Alice, I\'m good!');
  sendMessage('Charlie', 'Alice', 'Hey Alice, meeting at 5?');
  sendMessage('Alice', 'Charlie', 'Yes, see you there.');

  // Read messages for users
  readMessages('Bob');
  readMessages('Alice');
  readMessages('Charlie');

  // Interactive console part: Allow user to send messages or read
  print('\nInteractive mode: Type "send [sender] [recipient] [message]" or "read [user]" or "exit"');
  while (true) {
    stdout.write('> ');
    String? input = stdin.readLineSync();
    if (input == null || input.toLowerCase() == 'exit') {
      print('Exiting messaging system.');
      break;
    }

    List<String> parts = input.split(' ');
    if (parts.isEmpty) continue;

    String command = parts[0].toLowerCase();
    if (command == 'send' && parts.length >= 4) {
      String sender = parts[1];
      String recipient = parts[2];
      String message = parts.sublist(3).join(' ');
      sendMessage(sender, recipient, message);
    } else if (command == 'read' && parts.length == 2) {
      String user = parts[1];
      readMessages(user);
    } else {
      print('Invalid command. Use "send [sender] [recipient] [message]" or "read [user]" or "exit"');
    }
  }
}

