@pragma('vm:entry-point')
void main() {
  // Set stdin to raw mode for single key presses
  stdin.echoMode = false;
  stdin.lineMode = false;

  String searchTerm = '';
  print('Search bar with autocomplete (type letters, Backspace to delete, Enter to select first, Esc to exit):');

  while (true) {
    // Read a single byte (key press)
    int byte = stdin.readByteSync();

    if (byte == 27) { // Esc key to exit
      print('\nExiting...');
      break;
    } else if (byte == 13) { // Enter key
      List<String> suggestions = getSuggestions(searchTerm);
      if (suggestions.isNotEmpty) {
        print('\nSelected: ${suggestions.first}');
      } else {
        print('\nNo match found.');
      }
      break;
    } else if (byte == 127) { // Backspace
      if (searchTerm.isNotEmpty) {
        searchTerm = searchTerm.substring(0, searchTerm.length - 1);
      }
    } else if (byte >= 32 && byte <= 126) { // Printable ASCII characters
      searchTerm += String.fromCharCode(byte);
    } else {
      continue; // Ignore other keys
    }

    // Clear the line and reprint the search term and suggestions
    stdout.write('\r\x1b[2K'); // Clear current line
    stdout.write('Search: $searchTerm');

    List<String> suggestions = getSuggestions(searchTerm);
    if (suggestions.isNotEmpty) {
      print('\nSuggestions: ${suggestions.join(', ')}');
    } else {
      print('\nNo suggestions.');
    }
  }

  // Reset stdin modes
  stdin.echoMode = true;
  stdin.lineMode = true;
}

// Function to get autocomplete suggestions based on prefix
List<String> getSuggestions(String prefix) {
  return wordList.where((word) => word.toLowerCase().startsWith(prefix.toLowerCase())).toList();
}

