      serverWs.add(syncedMessage);
      print('Server sent: $syncedMessage');
    });

    // Simulate server-side real-time updates pushed to client periodically
    Timer.periodic(Duration(seconds: 3), (timer) {
      if (serverWs.readyState == WebSocket.open) {
        final serverUpdate = 'Server real-time update: Current time ${DateTime.now()}';
        serverWs.add(serverUpdate);
        print('Server pushed: $serverUpdate');
      } else {
        timer.cancel();
      }
    });
  });

  // Connect a client to the server for real-time sync
  final client = await WebSocket.connect('ws://localhost:${server.port}');
  print('Client connected to server');

  // Listen for messages from server (real-time sync updates)
  final clientSubscription = client.listen((message) {
    print('Client received: $message');
    // Simulate client processing the synced data
    print('Client processed synced data');
  });

  // Simulate client-side real-time data changes and send to server for sync
  Timer.periodic(Duration(seconds: 2), (timer) async {
    if (client.readyState == WebSocket.open) {
      final clientUpdate = 'Client data change: Value ${DateTime.now()}';
      client.add(clientUpdate);
      print('Client sent: $clientUpdate');
    } else {
      timer.cancel();
    }
  });

  // Run the synchronization for 10 seconds, then clean up
  await Future.delayed(Duration(seconds: 10));
  print('Shutting down...');

  // Clean up
