import 'dart:isolate';
import 'dart:async';
import 'dart:io';

/// Entry point for the background task isolate.
/// This function runs a periodic timer that simulates a scheduled background task,
/// such as logging the current time every 5 seconds.
/// It communicates back to the main isolate via the provided SendPort.
@pragma('vm:entry-point')
void backgroundTask(SendPort sendPort) {
  // Schedule a periodic task
  Timer.periodic(Duration(seconds: 5), (timer) {
    final now = DateTime.now();
    print('Background task executed at $now');
    sendPort.send('Task completed at $now');
  });

  // Keep the isolate alive indefinitely for continuous scheduling
  // In a real scenario, you could add logic to stop the timer based on messages.
}

/// Main function that spawns a background isolate for task scheduling.
/// It sets up communication and keeps the program running to demonstrate the scheduling.
@pragma('vm:entry-point')
void main() async {
  print('Starting background task scheduling...');

  // Create a ReceivePort to listen for messages from the background isolate
  final receivePort = ReceivePort();

  // Spawn the background isolate, passing the SendPort for communication
  await Isolate.spawn(backgroundTask, receivePort.sendPort);

  // Listen for messages from the background task
  await for (var message in receivePort) {
    print('Main received: $message');
    // In this demo, we keep listening forever. In a real app, you could close the port after some condition.
  }

  // Note: This program will run indefinitely to keep scheduling tasks.
  // Press Ctrl+C to exit.
}

