const String storageFilePath = 'pending_forms.json';

@pragma('vm:entry-point')
void main() async {
  print('Offline Form Submission Simulator');
  print('=================================');

  // Simulate connectivity (randomly online or offline for demo)
  bool isOnline = Random().nextBool();
  print('Current status: ${isOnline ? "Online" : "Offline"}');

  // Collect form data from user input
  stdout.write('Enter your name: ');
  String name = stdin.readLineSync() ?? '';

  stdout.write('Enter your email: ');
  String email = stdin.readLineSync() ?? '';

  stdout.write('Enter your message: ');
  String message = stdin.readLineSync() ?? '';

  FormData form = FormData(name, email, message);

  if (isOnline) {
    // Simulate submission
    print('Submitting form online: $form');
    // Also process any pending forms
    await processPendingForms();
  } else {
    // Save to local storage
    print('Offline: Saving form to local storage.');
    await saveFormToStorage(form);
  }

  // Simulate coming online and processing
  print('\nSimulating coming online...');
  isOnline = true;
  await processPendingForms();

  print('Program ended.');
}

// Save form to local JSON file
Future<void> saveFormToStorage(FormData form) async {
  File file = File(storageFilePath);
  List<dynamic> pendingForms = [];

  if (await file.exists()) {
    String content = await file.readAsString();
    pendingForms = jsonDecode(content) as List<dynamic>;
  }

  pendingForms.add(form.toJson());
  await file.writeAsString(jsonEncode(pendingForms));
  print('Form saved: $form');
}

// Process pending forms from storage
Future<void> processPendingForms() async {
