// Simulates a device as an isolate that maintains a local state (a counter)
// and synchronizes it with other devices via message passing through a central hub.
void deviceIsolate(Map<String, dynamic> params) async {
  final SendPort hubSendPort = params['hubSendPort'];
  final int deviceId = params['deviceId'];
  final ReceivePort receivePort = ReceivePort();
  hubSendPort.send({'type': 'register', 'deviceId': deviceId, 'sendPort': receivePort.sendPort});

  int localCounter = 0;
  Timer.periodic(Duration(seconds: 2), (timer) {
    localCounter++;
    print('Device $deviceId: Local counter incremented to $localCounter. Requesting sync.');
    hubSendPort.send({'type': 'sync_request', 'deviceId': deviceId, 'counter': localCounter});
  });

  await for (var message in receivePort) {
    if (message is Map<String, dynamic> && message['type'] == 'sync_update') {
      localCounter = message['counter'];
      print('Device $deviceId: Synced counter to ${message['counter']}');
    }
  }
}

@pragma('vm:entry-point')
void main() async {
  print('Starting multi-device synchronization simulation...');

  // Central hub for synchronization
  final ReceivePort hubReceivePort = ReceivePort();
  final Map<int, SendPort> devicePorts = {};
  int globalCounter = 0;

  // Listen for messages from devices
  hubReceivePort.listen((message) {
    if (message is Map<String, dynamic>) {
      if (message['type'] == 'register') {
        final int deviceId = message['deviceId'];
        final SendPort deviceSendPort = message['sendPort'];
        devicePorts[deviceId] = deviceSendPort;
        print('Hub: Registered device $deviceId');
        // Send initial sync
        deviceSendPort.send({'type': 'sync_update', 'counter': globalCounter});
      } else if (message['type'] == 'sync_request') {
        final int deviceId = message['deviceId'];
        final int proposedCounter = message['counter'];
        // Simple sync logic: take the max counter
        if (proposedCounter > globalCounter) {
          globalCounter = proposedCounter;
          print('Hub: Updated global counter to $globalCounter from device $deviceId');
          // Broadcast to all devices
          for (var entry in devicePorts.entries) {
            entry.value.send({'type': 'sync_update', 'counter': globalCounter});
          }
        }
      }
    }
  });

  // Spawn two device isolates
  Isolate.spawn(deviceIsolate, {'hubSendPort': hubReceivePort.sendPort, 'deviceId': 1});
  Isolate.spawn(deviceIsolate, {'hubSendPort': hubReceivePort.sendPort, 'deviceId': 2});

  // Run the simulation for 10 seconds
  await Future.delayed(Duration(seconds: 10));
  print('Simulation ended.');

  // Clean up (in a real app, you'd handle shutdown properly)
  hubReceivePort.close();
}

