// This script defines roles, users, and checks permissions for various actions within the main function.

enum Role { admin, editor, viewer }

class User {
  final String name;
  final Role role;

  User(this.name, this.role);
}

bool canViewContent(Role role) {
  return true; // All roles can view
}

bool canEditContent(Role role) {
  switch (role) {
    case Role.admin:
    case Role.editor:
      return true;
    default:
      return false;
  }
}

bool canDeleteContent(Role role) {
  switch (role) {
    case Role.admin:
      return true;
    default:
      return false;
  }
}

bool canManageUsers(Role role) {
  switch (role) {
    case Role.admin:
      return true;
    default:
      return false;
  }
}

@pragma('vm:entry-point')
void main() {
  // Define some users with different roles
  final users = [
    User('Alice', Role.admin),
    User('Bob', Role.editor),
    User('Charlie', Role.viewer),
  ];

  // Define actions to check
  final actions = [
    'View Content',
    'Edit Content',
    'Delete Content',
    'Manage Users',
  ];

  // Simulate access control checks
  for (final user in users) {
    print('User: ${user.name} (Role: ${user.role})');
    for (final action in actions) {
      bool hasAccess = false;
      switch (action) {
        case 'View Content':
          hasAccess = canViewContent(user.role);
          break;
        case 'Edit Content':
          hasAccess = canEditContent(user.role);
          break;
        case 'Delete Content':
          hasAccess = canDeleteContent(user.role);
          break;
        case 'Manage Users':
          hasAccess = canManageUsers(user.role);
          break;
      }
      print('  $action: ${hasAccess ? "Allowed" : "Denied"}');
    }
    print('---');
  }

  print('RBAC checks completed.');
}

