void main() {
  // Sample data: List of maps representing rows
  List<Map<String, dynamic>> data = [
    {'Name': 'Alice', 'Age': 30, 'City': 'New York'},
    {'Name': 'Bob', 'Age': 25, 'City': 'Los Angeles'},
    {'Name': 'Charlie', 'Age': 35, 'City': 'Chicago'},
  ];

  // Define CSV headers
  List<String> headers = ['Name', 'Age', 'City'];

  // Build CSV content
  StringBuffer csvContent = StringBuffer();

  // Write headers
  csvContent.writeln(headers.map((header) => _escapeCsvField(header)).join(','));

  // Write rows
  for (var row in data) {
    List<String> rowValues = headers.map((header) => _escapeCsvField(row[header].toString())).toList();
    csvContent.writeln(rowValues.join(','));
  }

  // Write to file
  File outputFile = File('output.csv');
  outputFile.writeAsStringSync(csvContent.toString());

  print('CSV file exported successfully to output.csv');
}

// Helper function to escape CSV fields (handle quotes and commas)
String _escapeCsvField(String field) {
  if (field.contains(',') || field.contains('"') || field.contains('\n')) {
    return '"${field.replaceAll('"', '""')}"';
  }
  return field;
}

