/// A simple Dart program that implements user preference storage using a JSON file.
/// Preferences are stored in a file named 'preferences.json' in the current directory.

@pragma('vm:entry-point')
void main() async {
  // Define the file path for storing preferences
  const String prefsFilePath = 'preferences.json';

  // Sample user preferences as a Map
  Map<String, dynamic> userPrefs = {
    'theme': 'dark',
    'language': 'en',
    'notificationsEnabled': true,
    'volume': 80,
  };

  // Function to save preferences to a JSON file
  Future<void> savePreferences(Map<String, dynamic> prefs, String filePath) async {
    final file = File(filePath);
    final jsonString = jsonEncode(prefs);
    await file.writeAsString(jsonString);
    print('Preferences saved to $filePath');
  }

  // Function to load preferences from a JSON file
  Future<Map<String, dynamic>> loadPreferences(String filePath) async {
    final file = File(filePath);
    if (await file.exists()) {
      final jsonString = await file.readAsString();
      return jsonDecode(jsonString) as Map<String, dynamic>;
    } else {
      print('No preferences file found. Returning empty map.');
      return {};
    }
  }

  // Demonstrate saving preferences
  await savePreferences(userPrefs, prefsFilePath);

  // Demonstrate loading preferences
  final loadedPrefs = await loadPreferences(prefsFilePath);
  print('Loaded preferences: $loadedPrefs');

  // Optionally, modify and save again to show update
  loadedPrefs['theme'] = 'light';
  await savePreferences(loadedPrefs, prefsFilePath);

  // Load again to verify update
  final updatedPrefs = await loadPreferences(prefsFilePath);
  print('Updated preferences: $updatedPrefs');
}

