/// A simple WebSocket server implementing real-time collaboration for a shared whiteboard.
/// Clients can connect via WebSocket and send drawing commands, which are broadcast to all connected clients.
///
/// Example client message: {"type": "draw", "x": 10, "y": 20, "color": "red"}
/// The server broadcasts the same message to all other clients.
///
/// Run this script, then connect clients using WebSocket to ws://localhost:8080.
/// This is a server-side implementation; clients would need to be implemented separately (e.g., in browser JS or another Dart app).

@pragma('vm:entry-point')
void main() async {
  // List to hold all connected WebSocket clients.
  final List<WebSocket> clients = [];

  // Start the WebSocket server on port 8080.
  final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 8080);
  print('WebSocket server listening on ws://localhost:8080');

  // Handle incoming requests.
  await for (HttpRequest request in server) {
    if (WebSocketTransformer.isUpgradeRequest(request)) {
      // Upgrade the HTTP request to a WebSocket connection.
      final socket = await WebSocketTransformer.upgrade(request);
      clients.add(socket);
      print('Client connected. Total clients: ${clients.length}');

      // Listen for messages from this client.
      socket.listen(
        (message) {
          // Parse the message (assuming JSON).
          try {
            final jsonMessage = jsonDecode(message as String);
            print('Received message: $jsonMessage');

            // Broadcast the message to all other connected clients.
            for (final client in clients) {
              if (client != socket && client.readyState == WebSocket.open) {
                client.add(jsonEncode(jsonMessage));
              }
            }
          } catch (e) {
            print('Invalid message: $e');
          }
        },
        onDone: () {
          // Remove the client when connection closes.
          clients.remove(socket);
          print('Client disconnected. Total clients: ${clients.length}');
        },
        onError: (error) {
          print('Error: $error');
          clients.remove(socket);
        },
      );
    } else {
      // Not a WebSocket upgrade request.
      request.response
        ..statusCode = HttpStatus.forbidden
        ..close();
    }
  }
}

