/// This is a complete Dart program demonstrating secure API authentication using OAuth2
/// Client Credentials Grant flow. It fetches an access token and uses it to make
/// an authenticated API request.
///
/// Note: Replace placeholders (e.g., clientId, clientSecret, tokenUrl, apiUrl) with
/// actual values for a real OAuth2 provider (e.g., Google, Auth0). This is a template
/// and will not run with real authentication without valid credentials.
///
/// For demonstration, this code assumes a hypothetical API. In practice, ensure
/// the API supports OAuth2 Client Credentials flow.

@pragma('vm:entry-point')
Future<void> main() async {
  // Placeholder values - replace with real ones
  const String clientId = 'your_client_id';
  const String clientSecret = 'your_client_secret';
  const String tokenUrl = 'https://example.com/oauth/token'; // e.g., 'https://oauth2.googleapis.com/token'
  const String apiUrl = 'https://example.com/api/protected'; // Protected API endpoint
  const String scope = 'read:protected'; // Optional scope

  try {
    // Step 1: Obtain access token using Client Credentials Grant
    final tokenResponse = await _getAccessToken(clientId, clientSecret, tokenUrl, scope);
    final tokenData = jsonDecode(tokenResponse);
    final accessToken = tokenData['access_token'] as String?;

    if (accessToken == null) {
      print('Error: Failed to obtain access token.');
      return;
    }

    print('Access Token obtained: $accessToken');

    // Step 2: Make authenticated API request
    final apiResponse = await _makeAuthenticatedRequest(apiUrl, accessToken);
    print('API Response: $apiResponse');
  } catch (e) {
    print('Error during authentication or API call: $e');
  }
}

/// Fetches an OAuth2 access token using Client Credentials Grant.
Future<String> _getAccessToken(String clientId, String clientSecret, String tokenUrl, String scope) async {
  final client = HttpClient();
  try {
    final request = await client.postUrl(Uri.parse(tokenUrl));
    request.headers.set(HttpHeaders.contentTypeHeader, 'application/x-www-form-urlencoded');

    // Basic Auth for client credentials
    final auth = base64Encode(utf8.encode('$clientId:$clientSecret'));
    request.headers.set(HttpHeaders.authorizationHeader, 'Basic $auth');

    // Body for client credentials grant
    final body = utf8.encode('grant_type=client_credentials${scope.isNotEmpty ? '&scope=$scope' : ''}');
    request.add(body);

    final response = await request.close();
    final responseBody = await response.transform(utf8.decoder).join();

    if (response.statusCode != 200) {
      throw HttpException('Failed to get token: ${response.statusCode} - $responseBody');
    }

    return responseBody;
  } finally {
    client.close();
  }
}

/// Makes an authenticated GET request to the API using the access token.
Future<String> _makeAuthenticatedRequest(String apiUrl, String accessToken) async {
  final client = HttpClient();
  try {
    final request = await client.getUrl(Uri.parse(apiUrl));
    request.headers.set(HttpHeaders.authorizationHeader, 'Bearer $accessToken');

    final response = await request.close();
    final responseBody = await response.transform(utf8.decoder).join();

    if (response.statusCode != 200) {
      throw HttpException('API request failed: ${response.statusCode} - $responseBody');
    }

    return responseBody;
  } finally {
    client.close();
  }
}

