import 'dart:io';
import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Simple in-app referral program simulation
  // Data structures to hold users, referral codes, and referrals
  Map<String, String> userReferralCodes = {}; // userId -> referralCode
  Map<String, List<String>> userReferrals = {}; // userId -> list of referred userIds
  Map<String, int> userRewards = {}; // userId -> reward points

  // Function to generate a unique referral code
  String generateReferralCode(String userId) {
    return '$userId-${Random().nextInt(10000)}';
  }

  // Function to register a new user
  void registerUser(String userId) {
    if (userReferralCodes.containsKey(userId)) {
      print('User $userId already exists.');
      return;
    }
    String code = generateReferralCode(userId);
    userReferralCodes[userId] = code;
    userReferrals[userId] = [];
    userRewards[userId] = 0;
    print('User $userId registered with referral code: $code');
  }

  // Function to refer a friend
  void referFriend(String referrerId, String newUserId, String referralCode) {
    if (!userReferralCodes.containsKey(referrerId)) {
      print('Referrer $referrerId does not exist.');
      return;
    }
    if (userReferralCodes[referrerId] != referralCode) {
      print('Invalid referral code for $referrerId.');
      return;
    }
    if (userReferralCodes.containsKey(newUserId)) {
      print('New user $newUserId already exists.');
      return;
    }

    // Register the new user
    registerUser(newUserId);

    // Add to referrals
    userReferrals[referrerId]!.add(newUserId);

    // Reward both
    userRewards[referrerId] = (userRewards[referrerId] ?? 0) + 10; // 10 points for referrer
    userRewards[newUserId] = (userRewards[newUserId] ?? 0) + 5; // 5 points for new user
    print('Referral successful! $referrerId referred $newUserId.');
    print('$referrerId now has ${userRewards[referrerId]} points.');
    print('$newUserId now has ${userRewards[newUserId]} points.');
  }

  // Function to check rewards and referrals
  void checkStatus(String userId) {
    if (!userReferralCodes.containsKey(userId)) {
      print('User $userId does not exist.');
      return;
    }
    print('User $userId:');
    print('Referral Code: ${userReferralCodes[userId]}');
    print('Referred Users: ${userReferrals[userId]}');
    print('Reward Points: ${userRewards[userId]}');
  }

  // Interactive loop
  print('Welcome to the In-App Referral Program Simulator!');
  print('Commands: register <userId>, refer <referrerId> <newUserId> <code>, check <userId>, exit');

  while (true) {
    stdout.write('Enter command: ');
    String? input = stdin.readLineSync();
    if (input == null || input.toLowerCase() == 'exit') {
      print('Exiting...');
      break;
    }

    List<String> parts = input.split(' ');
    if (parts.isEmpty) continue;

    String command = parts[0].toLowerCase();
    if (command == 'register' && parts.length == 2) {
      registerUser(parts[1]);
    } else if (command == 'refer' && parts.length == 4) {
      referFriend(parts[1], parts[2], parts[3]);
    } else if (command == 'check' && parts.length == 2) {
      checkStatus(parts[1]);
    } else {
      print('Invalid command. Try: register <userId>, refer <referrerId> <newUserId> <code>, check <userId>, exit');
    }
  }
}

