  final Map<String, Function(List<String>)> commands = {
    'help': (args) {
      print('Available commands:');
      print('  help - Show this help message');
      print('  log <message> - Log a message to console');
      print('  echo <text> - Echo back the provided text');
      print('  exit - Exit the debug console');
    },
    'log': (args) {
      if (args.isEmpty) {
        print('Error: log requires a message.');
      } else {
        print('LOG: ${args.join(' ')}');
      }
    },
    'echo': (args) {
      if (args.isEmpty) {
        print('Error: echo requires text.');
      } else {
        print('ECHO: ${args.join(' ')}');
      }
    },
    'exit': (args) {
      print('Exiting debug console.');
      exit(0);
    },
  };

  // Main loop to read input
  while (true) {
    stdout.write('> ');
    String? input = stdin.readLineSync();
    if (input == null || input.trim().isEmpty) continue;

    List<String> parts = input.trim().split(' ');
    String cmd = parts[0].toLowerCase();
    List<String> args = parts.length > 1 ? parts.sublist(1) : [];

    if (commands.containsKey(cmd)) {
      commands[cmd]!(args);
    } else {
      print('Unknown command: $cmd. Type "help" for available commands.');
    }
  }
}

