  List<bool> dp = List.filled(target + 1, false);
  dp[0] = true;

  for (int num in nums) {
    // Traverse backwards to avoid using the same number twice
    for (int i = target; i >= num; i--) {
      if (dp[i - num]) {
        dp[i] = true;
      }
    }
  }

  if (dp[target]) {
    print('Can partition into two subsets with equal sum.');
  } else {
    print('Cannot partition into two subsets with equal sum.');
  }
}

