import 'dart:math';

class AVLNode {
  int key;
  AVLNode? left;
  AVLNode? right;
  int height;

  AVLNode(this.key)
      : left = null,
        right = null,
        height = 1;
}

class AVLTree {
  AVLNode? root;

  int _height(AVLNode? node) => node?.height ?? 0;

  int _balance(AVLNode? node) =>
      node == null ? 0 : _height(node.left) - _height(node.right);

  AVLNode _rightRotate(AVLNode y) {
    AVLNode x = y.left!;
    AVLNode T2 = x.right!;

    // Perform rotation
    x.right = y;
    y.left = T2;

    // Update heights
    y.height = max(_height(y.left), _height(y.right)) + 1;
    x.height = max(_height(x.left), _height(x.right)) + 1;

    // Return new root
    return x;
  }

  AVLNode _leftRotate(AVLNode x) {
    AVLNode y = x.right!;
    AVLNode T2 = y.left!;

    // Perform rotation
    y.left = x;
    x.right = T2;

    // Update heights
    x.height = max(_height(x.left), _height(x.right)) + 1;
    y.height = max(_height(y.left), _height(y.right)) + 1;

    // Return new root
    return y;
  }

  AVLNode _insert(AVLNode? node, int key) {
    // 1. Perform normal BST insertion
    if (node == null) {
      return AVLNode(key);
    }

    if (key < node.key) {
      node.left = _insert(node.left, key);
