class RedBlackTree<T extends Comparable> {
  RBNode<T>? root;

  void insert(T key) {
    RBNode<T> node = RBNode<T>(key);
    RBNode<T>? y;
    RBNode<T>? x = root;

    while (x != null) {
      y = x;
      if (node.key.compareTo(x.key) < 0) {
        x = x.left;
      } else {
        x = x.right;
      }
    }
    node.parent = y;
    if (y == null) {
      root = node;
    } else if (node.key.compareTo(y.key) < 0) {
      y.left = node;
    } else {
      y.right = node;
    }
    node.color = Color.red;
    _insertFixup(node);
  }

