            z = z.parent!;
            _rightRotate(z);
          }
          z.parent!.color = Color.black;
          z.parent!.parent!.color = Color.red;
          if (z.parent!.parent != null) {
            _leftRotate(z.parent!.parent!);
          }
        }
      }
    }
    root?.color = Color.black;
  }

  void _leftRotate(RBNode<T> x) {
    RBNode<T>? y = x.right;
    if (y == null) return;
    x.right = y.left;
    if (y.left != null) {
      y.left!.parent = x;
    }
