    } else {
      x.parent!.right = y;
    }
    y.left = x;
    x.parent = y;
  }

  void _rightRotate(RBNode<T> y) {
    RBNode<T>? x = y.left;
    if (x == null) return;
    y.left = x.right;
    if (x.right != null) {
